	index = ( EventCode ) ;

	if ( index >= EMON_TOTAL_EVENTS || index < 0 ) {
		return PAPI_ENOEVNT;
	}
	strncpy( name, EMON_native_table[index].description, len );

	return ( PAPI_OK );
}


