/**
 * @file    io_basic.c
 * @author  Kevin A. Huck
 *          khuck@uoregon.edu
 * test case for I/O component
 *
 *
 * @brief
 *  This file is a very simple example test and Makefile that acat
 *    as a guideline on how to add tests to components.
 *  The papi configure and papi Makefile will take care of the compilation
 *    of the component tests (if all tests are added to a directory named
 *    'tests' in the specific component dir).
 *    See components/README for more details.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "papi.h"
#include "papi_test.h"

#define NUM_EVENTS 3

int main (int argc, char **argv)
{

    int retval,i;
    int EventSet = PAPI_NULL;
    long long values[NUM_EVENTS];
    const PAPI_component_info_t *cmpinfo = NULL;
    int numcmp,cid,example_cid=-1;
    int code,maximum_code=0;
    char event_name[PAPI_MAX_STR_LEN];
    PAPI_event_info_t event_info;
    int quiet=0;

    /* Set TESTS_QUIET variable */
    quiet=tests_quiet( argc, argv );

    /* PAPI Initialization */
    retval = PAPI_library_init( PAPI_VER_CURRENT );
    if ( retval != PAPI_VER_CURRENT ) {
        test_fail(__FILE__, __LINE__,"PAPI_library_init failed\n",retval);
    }

    if (!quiet) {
        printf( "Testing I/O component with PAPI %d.%d.%d\n",
                PAPI_VERSION_MAJOR( PAPI_VERSION ),
                PAPI_VERSION_MINOR( PAPI_VERSION ),
                PAPI_VERSION_REVISION( PAPI_VERSION ) );
    }

    /* Find our component */

    numcmp = PAPI_num_components();
    for( cid=0; cid<numcmp; cid++) {
        if ( (cmpinfo = PAPI_get_component_info(cid)) == NULL) {
            test_fail(__FILE__, __LINE__,
                    "PAPI_get_component_info failed\n", 0);
        }
        if (!quiet) {
            printf("\tComponent %d - %d events - %s\n", cid,
                    cmpinfo->num_native_events,
                    cmpinfo->name);
        }
        if (strstr(cmpinfo->name,"io")) {
            /* FOUND! */
            example_cid=cid;
        }
    }


    if (example_cid<0) {
        test_skip(__FILE__, __LINE__,
                "Example component not found\n", 0);
    }

    if (!quiet) {
        printf("\nFound io Component at id %d\n",example_cid);
        printf("\nListing all events in this component:\n");
    }

    /**************************************************/
    /* Listing all available events in this component */
    /* Along with descriptions                        */
    /**************************************************/
    code = PAPI_NATIVE_MASK;

    retval = PAPI_enum_cmp_event( &code, PAPI_ENUM_FIRST, example_cid );

    while ( retval == PAPI_OK ) {
        if (PAPI_event_code_to_name( code, event_name )!=PAPI_OK) {
            printf("Error translating %#x\n",code);
            test_fail( __FILE__, __LINE__,
                    "PAPI_event_code_to_name", retval );
        }

        if (PAPI_get_event_info( code, &event_info)!=PAPI_OK) {
            printf("Error getting info for event %#x\n",code);
            test_fail( __FILE__, __LINE__,
                    "PAPI_get_event_info()", retval );
        }

        if (!quiet) {
            printf("\tEvent %#x: %s -- %s\n",
                    code,event_name,event_info.long_descr);
        }

        maximum_code=code;

        retval = PAPI_enum_cmp_event( &code, PAPI_ENUM_EVENTS, example_cid );

    }
    if (!quiet) printf("\n");

    /**********************************/
    /* Try accessing an invalid event */
    /**********************************/

    retval=PAPI_event_code_to_name( maximum_code+10, event_name );
    if (retval!=PAPI_ENOEVNT) {
        test_fail( __FILE__, __LINE__,
                "Failed to return PAPI_ENOEVNT on invalid event", retval );
    }

    /***********************************/
    /* Test the rchar event     */
    /***********************************/

    retval = PAPI_create_eventset( &EventSet );
    if ( retval != PAPI_OK ) {
        test_fail( __FILE__, __LINE__,
                "PAPI_create_eventset() failed\n", retval );
    }

    retval = PAPI_event_name_to_code("io:::rchar", &code);
    if ( retval != PAPI_OK ) {
        test_fail( __FILE__, __LINE__,
                "io:::rchar not found\n",retval );
    }

    retval = PAPI_add_event( EventSet, code);
    if ( retval != PAPI_OK ) {
        test_fail( __FILE__, __LINE__,
                "PAPI_add_events failed\n", retval );
    }

    retval = PAPI_start( EventSet );
    if ( retval != PAPI_OK ) {
        test_fail( __FILE__, __LINE__, 
                "PAPI_start failed\n",retval );
    }

    retval = PAPI_stop( EventSet, values );
    if ( retval != PAPI_OK ) {
        test_fail(  __FILE__, __LINE__, "PAPI_stop failed\n", retval);
    }

    if (!quiet) printf("Testing io:::rchar: %lld\n",values[0]);

    if (values[0]==0) {
        test_fail(  __FILE__, __LINE__, "Result should be != 0!\n", 0);
    }

    retval = PAPI_cleanup_eventset(EventSet);
    if (retval != PAPI_OK) {
        test_fail(  __FILE__, __LINE__, "PAPI_cleanup_eventset!\n", retval);
    }

    retval = PAPI_destroy_eventset(&EventSet);
    if (retval != PAPI_OK) {
        test_fail(  __FILE__, __LINE__, "PAPI_destroy_eventset!\n", retval);
    }

    EventSet=PAPI_NULL;


    /***********************************/
    /* Test the wchar event */
    /***********************************/

    retval = PAPI_create_eventset( &EventSet );
    if ( retval != PAPI_OK ) {
        test_fail( __FILE__, __LINE__,
                "PAPI_create_eventset() failed\n", retval );
    }

    retval = PAPI_event_name_to_code("io:::wchar", &code);
    if ( retval != PAPI_OK ) {
        test_fail( __FILE__, __LINE__,
                "io:::wchar not found\n",retval );
    }

    retval = PAPI_add_event( EventSet, code);
    if ( retval != PAPI_OK ) {
        test_fail( __FILE__, __LINE__,
                "PAPI_add_events failed\n", retval );
    }

    retval = PAPI_start( EventSet );
    if ( retval != PAPI_OK ) {
        test_fail( __FILE__, __LINE__, 
                "PAPI_start failed\n",retval );
    }

    retval = PAPI_stop( EventSet, values );
    if ( retval != PAPI_OK ) {
        test_fail(  __FILE__, __LINE__, "PAPI_stop failed\n", retval);
    }

    if (!quiet) printf("Testing io:::wchar: %lld\n",values[0]);

    if (values[0]==0) {
        test_fail(  __FILE__, __LINE__, "Result should be != 0!\n", 0);
    }


    /***********************************/
    /* Test multiple reads             */
    /***********************************/

    retval = PAPI_start( EventSet );
    if ( retval != PAPI_OK ) {
        test_fail( __FILE__, __LINE__,
                "PAPI_start failed\n",retval );
    }

    for(i=0;i<10;i++) {

        retval=PAPI_read( EventSet, values);
        if ( retval != PAPI_OK ) {
            test_fail(  __FILE__, __LINE__, "PAPI_read failed\n", retval);
        }
        if (!quiet) printf("%lld ",values[0]);
    }

    retval = PAPI_stop( EventSet, values );
    if ( retval != PAPI_OK ) {
        test_fail(  __FILE__, __LINE__, "PAPI_stop failed\n", retval);
    }
    if (!quiet) printf("%lld\n",values[0]);

    //    if (values[0]!=i) {
    //   test_fail(  __FILE__, __LINE__, "Result wrong!\n", 0);
    //}

    /***********************************/
    /* Test PAPI_reset()               */
    /***********************************/

    retval = PAPI_reset( EventSet);
    if ( retval != PAPI_OK ) {
        test_fail( __FILE__, __LINE__,
                "PAPI_reset() failed\n",retval );
    }

    retval = PAPI_start( EventSet );
    if ( retval != PAPI_OK ) {
        test_fail( __FILE__, __LINE__,
                "PAPI_start failed\n",retval );
    }

    retval = PAPI_reset( EventSet);
    if ( retval != PAPI_OK ) {
        test_fail( __FILE__, __LINE__,
                "PAPI_reset() failed\n",retval );
    }

    retval = PAPI_stop( EventSet, values );
    if ( retval != PAPI_OK ) {
        test_fail(  __FILE__, __LINE__, "PAPI_stop failed\n", retval);
    }


    if (!quiet) printf("Testing after PAPI_reset(): %lld\n",
            values[0]);

    if (values[0]==0) {
        test_fail(  __FILE__, __LINE__, "Result zero!\n", 0);
    }

    retval = PAPI_cleanup_eventset(EventSet);
    if (retval != PAPI_OK) {
        test_fail(  __FILE__, __LINE__, "PAPI_cleanup_eventset!\n", retval);
    }

    retval = PAPI_destroy_eventset(&EventSet);
    if (retval != PAPI_OK) {
        test_fail(  __FILE__, __LINE__, "PAPI_destroy_eventset!\n", retval);
    }

    EventSet=PAPI_NULL;


    /***********************************/
    /* Test multiple events            */
    /***********************************/

    if (!quiet) printf("Testing Multiple Events: ");

    retval = PAPI_create_eventset( &EventSet );
    if ( retval != PAPI_OK ) {
        test_fail( __FILE__, __LINE__,
                "PAPI_create_eventset() failed\n", retval );
    }

    retval = PAPI_event_name_to_code("io:::rchar", &code);
    if ( retval != PAPI_OK ) {
        test_fail( __FILE__, __LINE__,
                "io:::rchar not found\n",retval );
    }

    retval = PAPI_add_event( EventSet, code);
    if ( retval != PAPI_OK ) {
        test_fail( __FILE__, __LINE__,
                "PAPI_add_events failed\n", retval );
    }

    retval = PAPI_event_name_to_code("io:::wchar", &code);
    if ( retval != PAPI_OK ) {
        test_fail( __FILE__, __LINE__,
                "io:::wchar not found\n",retval );
    }

    retval = PAPI_add_event( EventSet, code);
    if ( retval != PAPI_OK ) {
        test_fail( __FILE__, __LINE__,
                "PAPI_add_events failed\n", retval );
    }

    retval = PAPI_event_name_to_code("io:::read_bytes", &code);
    if ( retval != PAPI_OK ) {
        test_fail( __FILE__, __LINE__,
                "io:::read_bytes not found\n",retval );
    }

    retval = PAPI_add_event( EventSet, code);
    if ( retval != PAPI_OK ) {
        test_fail( __FILE__, __LINE__,
                "PAPI_add_events failed\n", retval );
    }


    retval = PAPI_start( EventSet );
    if ( retval != PAPI_OK ) {
        test_fail( __FILE__, __LINE__,
                "PAPI_start failed\n",retval );
    }

    retval = PAPI_stop( EventSet, values );
    if ( retval != PAPI_OK ) {
        test_fail(  __FILE__, __LINE__, "PAPI_stop failed\n", retval);
    }

    if (!quiet) {
        for(i=0;i<3;i++) {
            printf("%lld ",values[i]);
        }
        printf("\n");
    }

    if (values[0]==0) {
        test_fail(  __FILE__, __LINE__, "Result should be != 0!\n", 0);
    }

    retval = PAPI_cleanup_eventset(EventSet);
    if (retval != PAPI_OK) {
        test_fail(  __FILE__, __LINE__, "PAPI_cleanup_eventset!\n", retval);
    }

    retval = PAPI_destroy_eventset(&EventSet);
    if (retval != PAPI_OK) {
        test_fail(  __FILE__, __LINE__, "PAPI_destroy_eventset!\n", retval);
    }

    EventSet=PAPI_NULL;

    /***********************************/
    /* Test writing to an event        */
    /***********************************/

    if (!quiet) printf("Testing Write\n");

    retval = PAPI_create_eventset( &EventSet );
    if ( retval != PAPI_OK ) {
        test_fail( __FILE__, __LINE__,
                "PAPI_create_eventset() failed\n", retval );
    }

    retval = PAPI_event_name_to_code("io:::rchar", &code);
    if ( retval != PAPI_OK ) {
        test_fail( __FILE__, __LINE__,
                "io:::rchar not found\n",retval );
    }

    retval = PAPI_add_event( EventSet, code);
    if ( retval != PAPI_OK ) {
        test_fail( __FILE__, __LINE__,
                "PAPI_add_events failed\n", retval );
    }

    retval = PAPI_event_name_to_code("io:::read_bytes", &code);
    if ( retval != PAPI_OK ) {
        test_fail( __FILE__, __LINE__,
                "io:::read_bytes not found\n",retval );
    }

    retval = PAPI_add_event( EventSet, code);
    if ( retval != PAPI_OK ) {
        test_fail( __FILE__, __LINE__,
                "PAPI_add_events failed\n", retval );
    }

    retval = PAPI_event_name_to_code("io:::wchar", &code);
    if ( retval != PAPI_OK ) {
        test_fail( __FILE__, __LINE__,
                "io:::wchar not found\n",retval );
    }

    retval = PAPI_add_event( EventSet, code);
    if ( retval != PAPI_OK ) {
        test_fail( __FILE__, __LINE__,
                "PAPI_add_events failed\n", retval );
    }


    retval = PAPI_start( EventSet );
    if ( retval != PAPI_OK ) {
        test_fail( __FILE__, __LINE__,
                "PAPI_start failed\n",retval );
    }

    retval = PAPI_read ( EventSet, values );
    if ( retval != PAPI_OK ) {
        test_fail( __FILE__, __LINE__,
                "PAPI_read failed\n",retval );
    }

    if (!quiet) {
        printf("Before values: ");
        for(i=0;i<3;i++) {
            printf("%lld ",values[i]);
        }
        printf("\n");
    }

    values[0]=100;
    values[1]=200;
    values[2]=300;

    retval = PAPI_write ( EventSet, values );
    if ( retval != PAPI_OK ) {
        test_fail( __FILE__, __LINE__,
                "PAPI_write failed\n",retval );
    }

    retval = PAPI_stop( EventSet, values );
    if ( retval != PAPI_OK ) {
        test_fail(  __FILE__, __LINE__, "PAPI_stop failed\n", retval);
    }

    if (!quiet) {
        printf("After values: ");
        for(i=0;i<3;i++) {
            printf("%lld ",values[i]);
        }
        printf("\n");
    }


    if (values[0]==0) {
        test_fail(  __FILE__, __LINE__, "Result should be != 0!\n", 0);
    }

    retval = PAPI_cleanup_eventset(EventSet);
    if (retval != PAPI_OK) {
        test_fail(  __FILE__, __LINE__, "PAPI_cleanup_eventset!\n", retval);
    }

    retval = PAPI_destroy_eventset(&EventSet);
    if (retval != PAPI_OK) {
        test_fail(  __FILE__, __LINE__, "PAPI_destroy_eventset!\n", retval);
    }

    EventSet=PAPI_NULL;


    /************/
    /* All Done */
    /************/

    if (!quiet) printf("\n");

    test_pass( __FILE__ );

    return 0;
}

