            sprintf(event_name_str, "pci_bandwidth_rate:device=%i:%s", dev, variant_str);
        } else {
            sprintf(event_name_str, "pci_bandwidth_rate:device=%i:%s=%i", dev, variant_str, (int) subvariant);
