        sprintf(event_name_str, "device_brand:device=%i", dev);
    } else if (strcmp(name, "rsmi_dev_name_get") == 0) {
        sprintf(event_name_str, "device_name:device=%i", dev);
    } else if (strcmp(name, "rsmi_dev_serial_number_get") == 0) {
