            case ROCS_XGMI_BW_VARIANT__MAX:
                sprintf(event_descr_str, "%s.", "Maximum bandwidth between devices");
                break;
            default:
                return NULL;
        }
    } else {
        return NULL;
    }

    return papi_strdup(event_descr_str);
}

