    }

    rsmi_status_t status;
    rsmi_dev_perf_level_t data;
    if (mode == ROCS_ACCESS_MODE__READ) {
        status = rsmi_dev_perf_level_get_p(event->device, &data);
        if (status != RSMI_STATUS_SUCCESS) {
            return PAPI_EMISC;
        }
