    if (!(rocmsmi_ctx->state & ROCS_EVENTS_RUNNING)) {
        return PAPI_EMISC;
    }

    return rocs_ctx_read(rocmsmi_ctl->rocs_ctx, values);
}

static int
_rocm_smi_write(hwd_context_t *ctx, hwd_control_state_t *ctrl, long long *values)
{
