		return ( _papi_pfm_ntv_code_to_descr( EventCode, ntv_descr, len ) );
	else {
#if defined(HAVE_PFM_GET_EVENT_DESCRIPTION)
		pfmw_get_event_description( EventCode ^ PAPI_NATIVE_MASK, ntv_descr,
