//-----------------------------------------------------------------------------
// benchStats: Reads a CSV file of three columns; and produces various stats
// for each column. 
//-----------------------------------------------------------------------------


#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <papi.h>
#include "papi_test.h" 
#include <sys/time.h>

typedef struct {
   double init;
   double pcpVal;
} BenchData_t;

//-----------------------------------------------------------------------------
// qsort comparison to sort benchData array into ascending order of Init.
//-----------------------------------------------------------------------------
int sortAscBDInit(const void *vA, const void *vB) {
   BenchData_t *sA=(BenchData_t*) vA;        // recast to cmp type.
   BenchData_t *sB=(BenchData_t*) vB;        // ..

   if (sA->init < sB->init) return(-1);      // move cA toward front of list.
   if (sA->init > sB->init) return( 1);      // move cA toward end of list.
   return(0);                                // equality.
} // end routine.


//-----------------------------------------------------------------------------
// qsort comparison to sort benchData array into ascending order of pcpVal.
//-----------------------------------------------------------------------------
int sortAscBDPCP(const void *vA, const void *vB) {
   BenchData_t *sA=(BenchData_t*) vA;       // recast to cmp type.
   BenchData_t *sB=(BenchData_t*) vB;       // ..

   if (sA->pcpVal < sB->pcpVal) return(-1); // move cA toward front of list.
   if (sA->pcpVal > sB->pcpVal) return( 1); // move cA toward end of list.
   return(0);                               // equality.
} // end routine.


//-----------------------------------------------------------------------------
// median of sorted fRec init value array, for count elements.
// if count is odd, median is at (count/2).  e.g. count=7, 7/2=3, a[3] is it.
// if count is even, median is average of (count/2)-1 and (count/2). e.g. 
// count=8, a[3]+a[4] are two center values.
//-----------------------------------------------------------------------------
double median_BDInit(BenchData_t* fRec, int count) {
   if ((count&1)) return fRec[(count>>1)].init;          // median if count is odd.
   return ( (fRec[(count>>1)-1].init +
             fRec[(count>>1)].init)/2.0 );               // median if count is even.
} // end routine.   


//-----------------------------------------------------------------------------
// median of sorted fRec pcp value array, for count elements.
// if count is odd, median is at (count/2).  e.g. count=7, 7/2=3, a[3] is it.
// if count is even, median is average of (count/2)-1 and (count/2). e.g. 
// count=8, a[3]+a[4] are two center values.
//-----------------------------------------------------------------------------
double median_BDPCP(BenchData_t* fRec, int count) {
   if ((count&1)) return fRec[(count>>1)].pcpVal;        // median if count is odd.
   return ( (fRec[(count>>1)-1].pcpVal +
             fRec[(count>>1)].pcpVal)/2.0 );             // median if count is even.
} // end routine.   


//-----------------------------------------------------------------------------
// Write a rough ASCII histogram.
//-----------------------------------------------------------------------------

void histogram(int *BinCount, int bins, int total, double minVal, double width) {
   int i;
   double ctr, pcnt;
   for (i=0; i<bins; i++) {
      ctr = minVal + ( (i+.5)*width);                    // compute bin center.
      pcnt = (100.*BinCount[i]) / (total+0.0);           // compute percentage of values.
      printf("%8.1f, %8i, =%5.2f%%\n", ctr, BinCount[i], pcnt);
   }
} // end routine.


//-----------------------------------------------------------------------------
// MAIN.
//-----------------------------------------------------------------------------

int main(int argc, char **argv) {                                       // args to set filename.
   int i,j,ret;
   FILE *Inp;
   int Block = 64;
   BenchData_t *fRec = calloc(Block, sizeof(BenchData_t));              // Make some initial space.
   char title1[128], title2[128];
   int count=0, size=Block;                                             // records we have, size of malloc.

   if (argc != 2) {                                                     // progname inpfile 
      fprintf(stderr, "You must specify a CSV file on the command line.\n");
      exit(-1);
   }

   Inp =fopen(argv[1], "r");                                            // Open arg1 as input file.
   if (Inp == NULL) {                                                   // In case of failure...
      fprintf(stderr, "Error reading file %s.\n", argv[1]);             // .. report it.
      exit(-1);                                                         // .. exit.
   }

   ret = fscanf(Inp, "%128[^,],%128[^\n]", title1, title2);  // Read the three titles.
   if (ret !=2) {                                                             // If we did not get 3, 
      fprintf(stderr, "File Format Error, read %i of 2 expected column titles in file '%s'.\n", ret, argv[1]);
      fclose(Inp);
      exit(-1);
   }

   while (1) {                                                          // We break out of this.
      ret = fscanf(Inp, "%lf,%*[ ]%lf\n", &fRec[count].init, &fRec[count].pcpVal);  // read two values.
      if (ret == EOF) break;                                            // quiet break at EOF.
      if (ret != 2) {                                                   // If we did not get 3 values,
         fprintf(stderr, "File Format Error, read %i of 2 expected column values in file '%s', line %i.\n", ret, argv[1], count+2);
         fclose(Inp);
         free(fRec);
         exit(-1);
      }

      count++;                                                          // increment count of lines.
      if (count == size) {                                              // If that was last in size,
         size += Block;                                                 // Need to add another chunk.
         fRec = realloc(fRec, size*sizeof(BenchData_t));                // make more space.
         if (fRec == NULL) {
            fprintf(stderr, "Memory failure, failed to realloc(fRec, %i)\n", size);
            fclose(Inp);
            exit(-1);
         }
      } // end if realloc needed.
   } // end of all reading.

   fclose(Inp);                                                         // Done with this file.
   fprintf(stderr, "Read a total of %i data lines.\n", count);

   // We can go ahead and find the min, max, max-but-1 and average for both Init and PCP.
   double minInit=fRec[0].init;
   double maxInit=minInit;
   double firstInit=minInit;
   double avgInit=minInit; 
   double maxBut1Init = fRec[1].init;                                  // start this at second value.

   double minPCP=fRec[0].pcpVal;
   double maxPCP=minPCP;
   double firstPCP=minPCP;
   double avgPCP=minPCP; 
   double maxBut1PCP = fRec[1].pcpVal;                                  // start this at second value.

   for (i=1; i<count; i++) {                                            // check the rest.
      double v;
      v=fRec[i].init;                                                   // get it.
      if (v > maxInit) maxInit=v;
      if (v > maxBut1Init) maxBut1Init=v;
      if (v < minInit) minInit=v;
      avgInit += v;                                                     // build for average.

      v=fRec[i].pcpVal;                                                 // get it.
      if (v > maxPCP) maxPCP=v;
      if (v > maxBut1PCP) maxBut1PCP=v;
      if (v < minPCP) minPCP=v;
      avgPCP += v;                                                      // build for average.
   }

   avgInit /= ((double) count);                                         // compute average.
   avgPCP /= ((double) count);                                          // compute average.


   // The mode: This is the highest value in a histogram of values;
   // but that can be quite arbitary in picking the window size. We
   // use as our # of bins the square root of the count; and make 
   // the bin size the (max-min)/#bins.

   int maxBin, *InitBins=NULL, *ReadBins=NULL;                          // counters for compute.
   int bins = ceil(sqrtf((double) count));
   int expCount = round(((count+0.0) / (bins+0.0)));                    // expected count per bin.

   // Mode for Init. 
   qsort(fRec, count, sizeof(BenchData_t), sortAscBDInit);              // put in ascending order of Init time.

   double medInit = median_BDInit(fRec, count);                         // get the overall median. 
   double Initrange=(maxInit-minInit);                                  // compute the range.
   double Initbin=ceil(Initrange/bins);                                 // bin size.
   if (Initbin == 0.0) Initbin=1.0;                                     // If all the same, just one bin.
   InitBins = calloc(bins, sizeof(int));                                // make counters for them.

   for (i=0; i<count; i++) {                                            // for every record,
      double v = fRec[i].init - minInit;                                // ..value to bin.
      for (j=0; j<bins; j++) {                                          // ..search for bin.
         if (v < (j+1)*Initbin) break;                                  // ..if we found the bin, break.
      }

      InitBins[j]++;                                                    // Add to number in that bin.
   }

   maxBin = 0;                                                          // first bin is beginning of max.
   for (i=1; i<bins; i++) {
      if (InitBins[i] > InitBins[maxBin]) maxBin=i;                     // remember index of max bin.
   }

   double modeInit = minInit + ((maxBin+0.5) * Initbin);                // find the mode as centerpoint.
   int actInitCount = InitBins[maxBin];                                 // actual init count.


   // Mode for PCP. 
   qsort(fRec, count, sizeof(BenchData_t), sortAscBDPCP);               // put in ascending order of pcpVal.
   double medPCP = median_BDPCP(fRec, count);                           // get the overall median. 
   double PCPrange=(maxPCP-minPCP);                                     // compute the range.
   double PCPbin=ceil(PCPrange/bins);                                 // bin size.
   if (PCPbin == 0.0) PCPbin=1.0;                                       // If all the same, just one bin.
   ReadBins = calloc(bins, sizeof(int));                                // make counters for them.

   for (i=0; i<count; i++) {                                            // for every record,
      double v = fRec[i].pcpVal - minPCP;                               // ..value to bin.
      for (j=0; j<bins; j++) {                                          // ..search for bin.
         if (v < (j+1)*PCPbin) break;                                   // ..if we found the bin, break.
      }

      ReadBins[j]++;                                                    // Add to number in that bin.
   }

   maxBin = 0;                                                          // first bin is beginning of max.
   for (i=1; i<bins; i++) {
      if (ReadBins[i] > ReadBins[maxBin]) maxBin=i;                     // remember index of max bin.
   }

   double modePCP = minPCP + ((maxBin+0.5) * PCPbin);                   // find the mode as centerpoint.
   int actPCPCount = ReadBins[maxBin];                                  // actual init count.


   // Stats for init.

   printf("Stats for Initialization time in file '%s'.\n" , argv[1]   );
   printf("Sample Values                  ,%8i\n"  , count            );
   printf("Minimum uS                     ,%8.1f\n", minInit          );
   printf("Maximum uS                     ,%8.1f\n", maxInit          );
   printf("Average uS                     ,%8.1f\n", avgInit          );
   printf("Median  uS                     ,%8.1f\n", medInit          );
   printf("First   uS                     ,%8.1f\n", firstInit        );
   printf("Max w/o First                  ,%8.1f\n", maxBut1Init      );
   printf("Range   uS                     ,%8.1f\n", Initrange        );
   printf("Histogram Bins chosen          ,%8i\n"  , bins             );
   printf("Bin width uS                   ,%8.1f\n", Initbin          );
   printf("Mode (center highest Bin Count),%8.1f\n", modeInit         );
   printf("Mode Bin Count                 ,%8i\n"  , actInitCount     );
   printf("Bin Expected Count             ,%8i\n"  , expCount         );
   printf("\n");
   printf("Initialization Histogram:\n"
          "binCenter, Count, %% of Count\n");

   histogram(InitBins, bins, count, minInit, Initbin);

   printf("\n");
   printf("Stats for PCP event read time in file '%s'.\n" , argv[1]   );
   printf("Sample Values                  ,%8i\n"  , count            );
   printf("Minimum uS                     ,%8.1f\n", minPCP           );
   printf("Maximum uS                     ,%8.1f\n", maxPCP           );
   printf("Average uS                     ,%8.1f\n", avgPCP           );
   printf("Median  uS                     ,%8.1f\n", medPCP           );
   printf("First   uS                     ,%8.1f\n", firstPCP         );
   printf("Max w/o First                  ,%8.1f\n", maxBut1PCP       );
   printf("Range   uS                     ,%8.1f\n", PCPrange         );
   printf("Histogram Bins chosen          ,%8i\n"  , bins             );
   printf("Bin width uS                   ,%8.1f\n", PCPbin           );
   printf("Mode (center highest Bin Count),%8.1f\n", modePCP          );
   printf("Mode Bin Count                 ,%8i\n"  , actPCPCount      );
   printf("Bin Expected Count             ,%8i\n"  , expCount         );
   printf("\n");
   printf("Read Event Histogram:\n"
          "binCenter, Count, %% of Count\n");

   histogram(ReadBins, bins, count, minPCP, PCPbin);
   printf("\n");
   free(InitBins); InitBins=NULL;                                       // Lose this version of InitBins array.
   free(ReadBins); ReadBins=NULL;                                       // Lose this version of ReadBins array.
   free(fRec);
} // end main.

//-----------------------------------------------------------------------------
// This test does timing on reading an event; specifically a PCP event.
// The timing for the event can be read many times, and given as an average.
// The count and event to read are given on the command line in text, e.g.
// ./benchPCP 100 "perfevent.hwcounters.instructions.value:cpu0"
// will be read in a loop 100 times, the whole thing will be timed, and the
// time divided by 100 will be reported (avg time of a read). We do this to
// increase resolution; since our time is measured in microseconds (uS) by
// averaging many reads we can get greater accuracy.
//
// We also measure the time required to initiliaze PAPI (with the component),
// and report that.
//
// We will printf() both the initialization time and read time on the same line
// in CSV format.  If no arguments are given, we will printf() a header CSV
// line. Otherwise there must be exactly two arguments. Errors are printed to
// 'stderr'. This scheme allows a shell loop to produce a csv file with a
// header and many samples, to be processed to produce descriptive statistics
// separately (by spreadsheet or another program).
//-----------------------------------------------------------------------------

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <papi.h>
#include "papi_test.h" 
#include <sys/time.h>

#define mConvertUsec(timeval_) ((double) (timeval_.tv_sec*1000000+timeval_.tv_usec))     /* avoid typos, make it a double. */
static struct timeval t1, t2;
int EVENTREADS=0;

typedef union
{
   long long ll;
   unsigned long long ull;
   double    d;
   void *vp;
   unsigned char ch[8];
} convert_64_t;

//-----------------------------------------------------------------------------
// MAIN.
//-----------------------------------------------------------------------------

int main(int argc, char **argv) {                                       // args to set two events. 
   int i,ret;
   int EventSet = PAPI_NULL;
   char errMsg[1024];                                                   // space for an error message with more info.
   char *pcpName;                                                       // The pcp name.
   if (argc == 1) {                                                     // If no arguments given,
      printf("Initialize, Event Read Avg uS\n");                        // OUTPUT Header for CSV.
      return 0;                                                         // done.
   }

   if (argc != 3) {
      fprintf(stderr, "%s:%i ERROR Invalid number of arguments; must be 0 or 2.\n", __FILE__, __LINE__); // report.
      fprintf(stderr, "%s readsToAvg Event-Name\n", argv[0]);
      exit(-1);
   }

   // Get args.
   EVENTREADS = atoi(argv[1]);                                          // get event reads.
   if (EVENTREADS < 1) {
      fprintf(stderr, "%s:%i ERROR readsToAvg must be > 0.\n", __FILE__, __LINE__); // report.
      fprintf(stderr, "%s readsToAvg Event-Name\n", argv[0]); 
      exit(-1);
   }

   pcpName  = argv[2];                                                  // collect the pcp event name.

   gettimeofday(&t1, NULL);
   ret = PAPI_library_init( PAPI_VER_CURRENT );
   gettimeofday(&t2, NULL);

   if (ret != PAPI_VER_CURRENT) {                                       // if we failed,
      printf("ERROR PAPI library init failed.\n");                      // Show abort in file. 
      test_fail(__FILE__, __LINE__, "PAPI_library_init failed\n", ret); // report.
   }

   printf("%9.1f,", (mConvertUsec(t2)-mConvertUsec(t1)));               // OUTPUT PAPI library init time. 

// fprintf(stderr, "Benching Event Read with PAPI %d.%d.%d\n",
//    PAPI_VERSION_MAJOR( PAPI_VERSION ),
//    PAPI_VERSION_MINOR( PAPI_VERSION ),
//    PAPI_VERSION_REVISION( PAPI_VERSION ) );

   // Library is initialized.
   ret = PAPI_create_eventset(&EventSet);                               // Create an event. 
   if (ret != PAPI_OK) {                                                // If that failed, report and exit.
      fprintf(stderr, "ERROR PAPI_create_eventset failed.\n");
      test_fail(__FILE__, __LINE__, "PAPI_create_eventset failed.\n", ret);
   }

   ret=PAPI_add_named_event(EventSet,pcpName);                       // Try to add it for counting.
   if (ret != PAPI_OK) {                                             // If that failed, report it.
      sprintf(errMsg, "PAPI_add_named_event('%s') failed.\n", pcpName);
      printf("ERROR %s\n", errMsg);
      test_fail( __FILE__, __LINE__, errMsg, ret);
   }

   //----------------------------------------------------------------------------------------------
   // Testing, we just read each event EVENTREADS times, and record the times read.
   // We overwrite the previous result every time, we aren't interested in the values.
   // 'volatile' to avoid compiler optimizing out the loop.
   //----------------------------------------------------------------------------------------------
   long long pcpValue;

   // Begin event timing.
   ret = PAPI_start(EventSet);                                       // start counting.
   if (ret != PAPI_OK) {                                             // If that failed, report it.
      printf("ERROR PAPI_start EventSet failed.\n");                 // Show abort in file. 
      test_fail( __FILE__, __LINE__, "PAPI_start_event(EventSet) failed.\n", ret);  // report and exit.
   }                                                                 

   gettimeofday(&t1, NULL);
   for (i=0; i<EVENTREADS; i++) {                                    // For all the PCP iterations, 
      ret = PAPI_read(EventSet, &pcpValue);                          // .. read without a stop.
      if (ret != PAPI_OK) {                                          // .. If that failed, report it.
         printf("ERROR PAPI_read EventSet failed.\n");               // Show abort in file. 
         test_fail( __FILE__, __LINE__, "PAPI_read(EventSet) failed.\n", ret);
      }                                                              
   } 
   gettimeofday(&t2, NULL);

   ret = PAPI_stop(EventSet, &pcpValue);                             // stop counting, get final value.
   if (ret != PAPI_OK) {                                             // If that failed, report it.
      printf("ERROR PAPI_stop EventSet failed.\n");                  // Show abort in file. 
      test_fail( __FILE__, __LINE__, "PAPI_stop_event(PAPIEventSet, &papiValues[FINAL]) failed.\n", ret);
   }

   printf("%9.1f\n", (mConvertUsec(t2)-mConvertUsec(t1))/((double) EVENTREADS));  // compute average, finish line.

   ret = PAPI_cleanup_eventset(EventSet);                            // Try a cleanup.
   if (ret != PAPI_OK) {                                             // If that failed, report it.
      printf("ERROR PAPI_cleanup_eventset failed.\n");               // Show abort in file. 
      test_fail( __FILE__, __LINE__, "PAPI_cleanup_eventset(EventSet) failed.\n", ret);
   }

   ret = PAPI_destroy_eventset(&EventSet);                           // Deallocate. No memory leaks!
   if (ret != PAPI_OK) {                                             // If that failed, report it.
      printf("ERROR PAPI_destroy_eventset failed.\n");               // Show abort in file. 
      test_fail( __FILE__, __LINE__, "PAPI_destroy_eventset(EventSet) failed.\n", ret);
   }

   //----------------------------------------------------------------------------------------------
   // Done. cleanup.
   //----------------------------------------------------------------------------------------------
   PAPI_shutdown();                                                  // get out of papi.
// fprintf(stderr, "PAPI Shutdown completed.\n");                    // If we are verbose, 
// test_pass( __FILE__ );                                            // Note the test passed. 
   return 0;                                                         // Exit with all okay.
} // END main.

//----------------------------------------------------------------------------
// This test program exercises the functions within the linux-pcp.c component.
//-----------------------------------------------------------------------------

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <papi.h>
#include "papi_test.h" 
#include <sys/time.h>

#define mConvertUsec(timeval_) ((double) (timeval_.tv_sec*1000000+timeval_.tv_usec))     /* avoid typos, make it a double. */
static struct timeval t1, t2;

unsigned long dummyThreadId(void) { return(0); }                        // dummy return to give a thread id.

typedef union
{
   long long ll;
   unsigned long long ull;
   double    d;
   void *vp;
   unsigned char ch[8];
} convert_64_t;

//-----------------------------------------------------------------------------
// MAIN.
//-----------------------------------------------------------------------------

int main(int argc, char **argv) {                                       // args to allow quiet flags. 
   int i,k,m,code=0;
   int eventSetCount, ret;
   PAPI_event_info_t info;
   int cid=-1;                                                          // signal for not found.
   int EventSet = PAPI_NULL;
	int quiet=0;
   char errMsg[1024];                                                   // space for an error message with more info.
	quiet=tests_quiet( argc, argv );                                     // From papi_test.h.
   int firstTime = 1;                                                   // some things we want to run once.
   int retlen;

   gettimeofday(&t1, NULL);
   ret = PAPI_library_init( PAPI_VER_CURRENT );
   gettimeofday(&t2, NULL);
   if (!quiet) fprintf(stderr, "PAPI_Library_init run time = %9.1f uS\n", (mConvertUsec(t2)-mConvertUsec(t1)));

   if (ret != PAPI_VER_CURRENT) {                                       // if we failed, 
      test_fail(__FILE__, __LINE__, "PAPI_library_init failed\n", ret); // report.
   }


	if (!quiet) {
	   fprintf(stderr, "Testing PCP Component with PAPI %d.%d.%d\n",
			PAPI_VERSION_MAJOR( PAPI_VERSION ),
			PAPI_VERSION_MINOR( PAPI_VERSION ),
			PAPI_VERSION_REVISION( PAPI_VERSION ) );
	}

   // PAPI_init_thread should be run only once, immediately after 
   // library init. 
// ret = PAPI_thread_init(dummyThreadId);                               // PCP doesn't do anything, but should not err or crash on thread init.
// if (ret != PAPI_OK) {                                                // If we get an error, this tester needs updating; pcp code has changed.
//    test_fail(__FILE__, __LINE__, "PAPI_thread_init failed; this tester needs to be updated.\n", ret); // report.
// }

   // Find our component, pcp; 
   PAPI_component_info_t *aComponent;
   k = PAPI_num_components();                                           // get number of components.
   for (i=0; i<k && cid<0; i++) {                                       // while not found,
      aComponent = (PAPI_component_info_t*) PAPI_get_component_info(i); // get the component info.
      if (aComponent == NULL) {                                         // if we failed,
         sprintf(errMsg,  "PAPI_get_component_info(%i) failed, "
            "returned NULL. %i components reported.\n", i,k);
         test_fail(__FILE__, __LINE__, errMsg, 0);

      }

      if (strcmp("pcp", aComponent->name) == 0) cid=i;                  // If we found our match, record it.
   } // end search components.

   if (cid < 0) {                                                       // if no PCP component found,
      sprintf(errMsg, "Failed to find pcp component among %i "
            "reported components.\n", k);
      test_fail(__FILE__, __LINE__, errMsg, 0);                         // report it.
   }

	if (!quiet) {
	  fprintf(stderr, "Found PCP Component at id %d\n",cid);
	}

   // If the component is disabled, skip the test.
   if (aComponent->disabled) {
       test_skip(__FILE__,__LINE__,"Component pcp is disabled", 0);
       PAPI_shutdown();
       return 0;
   }

   // Library is initialized and pcp component is identified.

   // Set up to exercise the code for _pcp_ctl; it does nothing 
   // but prove it doesn't crash if called. The actual call to
   // PAPI_set_opt is below; it requires an eventset. 

   PAPI_option_t aDomOpt;                                            // make a domain option.
   aDomOpt.domain.def_cidx = cid;                                    // fill it out.
   aDomOpt.domain.domain = PAPI_DOM_ALL;                             // .. 

   // Begin enumeration of all events. 

   m=PAPI_NATIVE_MASK;                                               // Get the PAPI NATIVE mask.
   ret=PAPI_enum_cmp_event(&m,PAPI_ENUM_FIRST,cid);                  // Begin enumeration of ALL papi counters.
   if (ret != PAPI_OK) fprintf(stderr, "PAPI_enum_cmp_event returned %i [%s].\n", ret, PAPI_strerror(ret));
   if (ret != PAPI_OK) {                                             // If that failed, report and exit.
      test_fail(__FILE__, __LINE__, "PAPI_enum_cmp_event failed.\n",
         ret);
   }

   //----------------------------------------------
   // Setups are done, we begin the work work here.
   //----------------------------------------------
   int count = 0;
   if (!quiet) printf("Component Idx, Symbol, Units, Description, HexCode (this run only), Time Scope, PAPI_TYPE, Sample Value\n");

   do{                                                               // Enumerate all events.
      memset(&info,0,sizeof(PAPI_event_info_t));                     // Clear event info.
      k=m;                                                           // Make a copy of current code.

      // enumerate sub-events, with masks. For this test, we do not
      // have any! But we do this to test our enumeration works as
      // expected. First time through is guaranteed, of course.

      do{                                                            // enumerate masked events. 
         ret=PAPI_get_event_info(k,&info);                           // get name of k symbol.
         if (ret != PAPI_OK) {                                       // If that failed, report and exit.
            sprintf(errMsg, "PAPI_get_event_info(%i) failed.\n", k); // build message.
            test_fail(__FILE__, __LINE__, errMsg, ret);
         }

         // Test creating an event set.
         ret = PAPI_create_eventset(&EventSet);                      // Try it.
         if (ret != PAPI_OK) {                                       // If that failed, report and exit.
         test_fail(__FILE__, __LINE__, "PAPI_enum_create_eventset failed.\n", ret);
         }

         // Test adding and removing the event by name.
         ret=PAPI_add_named_event(EventSet,info.symbol);             // Try to add it for counting.
         if (ret != PAPI_OK) {                                       // If that failed, report it.
            retlen = snprintf(errMsg, PAPI_MAX_STR_LEN, "PAPI_add_named_event('%s') failed.\n", info.symbol);
            if (retlen <= 0 || PAPI_MAX_STR_LEN <= retlen)
              continue;
            test_fail( __FILE__, __LINE__, errMsg, ret);
         }

         // test _pcp_ctl function. Just need to do this once.

         if (firstTime) {
            aDomOpt.domain.eventset = EventSet;                         // ..
            ret = PAPI_set_opt(PAPI_DOMAIN, &aDomOpt);                  // force call to pcp_ctl.
            if (ret != PAPI_OK) {                                       // If that failed, report and exit.
               test_fail(__FILE__, __LINE__, "PAPI_set_opt failed.\n",
               ret);
            } 
         }   

         ret=PAPI_remove_named_event(EventSet,info.symbol);          // Try to remove it.
         if (ret != PAPI_OK) {                                       // If that failed, report it.
            retlen = snprintf(errMsg, PAPI_MAX_STR_LEN, "PAPI_remove_named_event('%s') failed.\n", info.symbol);
            if (retlen <= 0 || PAPI_MAX_STR_LEN <= retlen)
              continue;
            test_fail( __FILE__, __LINE__, errMsg, ret);
         }

         // Test getting code for name, consistency with enumeration.
         ret=PAPI_event_name_to_code(info.symbol, &code);            // Try to read the code from the name.
         if (ret != PAPI_OK) {                                       // If that failed, report it.
            retlen = snprintf(errMsg, PAPI_MAX_STR_LEN, "PAPI_event_name_to_code('%s') failed.\n", info.symbol);
            if (retlen <= 0 || PAPI_MAX_STR_LEN <= retlen)
              continue;
            test_fail( __FILE__, __LINE__, errMsg, ret);
         }

         // Papi can report a different code; k incremented by 1.
         // I am not clear on why it does that.
         if (code != k && code != (k+1)) {                           // If code retrieved is not the same, fail and report it.
            retlen = snprintf(errMsg, PAPI_MAX_STR_LEN, "PAPI_event_name_to_code('%s') "
               "returned code 0x%08X, expected 0x%08X. failure.\n", 
               info.symbol, code, k);
            if (retlen <= 0 || PAPI_MAX_STR_LEN <= retlen)
              continue;
            test_fail( __FILE__, __LINE__, errMsg, 0);               // report and fail.  
         }

         // Test getting name from code, consistency with info.
         char testName[PAPI_MAX_STR_LEN] = "";                       // needed for test.
         ret=PAPI_event_code_to_name(code, testName);                // turn code back into a name.
         if (ret != PAPI_OK) {                                       // If that failed, report it.
            retlen = snprintf(errMsg, PAPI_MAX_STR_LEN, "PAPI_event_code_to_name(('0x%08X') failed.\n", code);
            if (retlen <= 0 || PAPI_MAX_STR_LEN <= retlen)
              continue;
            test_fail( __FILE__, __LINE__, errMsg, ret);
         }

         if (strcmp(info.symbol, testName) != 0) {                   // If name retrieved is not the same, fail and report it.
            retlen = snprintf(errMsg, PAPI_MAX_STR_LEN, "PAPI_event_code_to_name(('0x%08X') "
               "returned name=\"'%s'\", expected \"%s\". failure.\n", 
               code, testName, info.symbol);
            if (retlen <= 0 || PAPI_MAX_STR_LEN <= retlen)
              continue;
            test_fail( __FILE__, __LINE__, errMsg, 0);               // Report and exit.
         }

         ret = PAPI_add_event(EventSet, code);                       // Try to add the event.
         if (ret != PAPI_OK) {                                       // If that failed, report it.
            sprintf(errMsg, "PAPI_add_event('0x%08X') failed.\n", code);
            test_fail( __FILE__, __LINE__, errMsg, ret);             // report and exit.
         }

         ret = PAPI_start(EventSet);                                 // start counting.
         if (ret != PAPI_OK) {                                       // If that failed, report it.
            sprintf(errMsg, "PAPI_start_event('0x%08X') failed.\n", code);
            test_fail( __FILE__, __LINE__, errMsg, ret);             // report and exit.
         }

         long long *values = NULL;                                   // pointer for us to malloc next.

         eventSetCount = PAPI_num_events(EventSet);                  // get the number of events in set.
         if (eventSetCount < 1) {
            test_fail( __FILE__, __LINE__, "PAPI_num_events(EventSet) failed.\n", ret);
         }

         values = calloc(eventSetCount, sizeof(long long));          // make zeroed space for it. 

         ret = PAPI_read(EventSet, values);                          // read without a stop.
         if (ret != PAPI_OK) {                                       // If that failed, report it.
            free(values);
            test_fail( __FILE__, __LINE__, "PAPI_read(EventSet) failed.\n", ret);
         }

         // Test doing something with it.
         count++;                                                    // bump count of items seen and added.
         if (!quiet) {
            printf("%i, %s, %s, %s, 0x%08x,", 
            info.component_index, info.symbol,info.units, 
            info.long_descr, info.event_code);
            convert_64_t cvt;
            cvt.ll = values[0];                                      // copy the value returned.

            if (info.timescope == PAPI_TIMESCOPE_SINCE_START) { 
               printf("SINCE START,");
            } else {
               printf("POINT,"); 
            }

            switch (info.data_type) {                                // based on type, 
               case PAPI_DATATYPE_INT64:
                  printf("INT64, %lli", cvt.ll);
                  break;                                             // END CASE.

               case PAPI_DATATYPE_UINT64:
                  printf("UINT64, %llu", cvt.ull);
                  break;                                             // END CASE.

               case PAPI_DATATYPE_FP64:
                  printf("FP64, %f", cvt.d);
                  break;                                             // END CASE.

               default:
                  printf("UNKNOWN TYPE, %p", cvt.vp);
                  break;                                             // END CASE.
            }

            printf("\n");   
         }

         ret = PAPI_reset(EventSet);                                 // Reset the event.
         if (ret != PAPI_OK) {                                       // If that failed, report and exit.
            free(values);
            test_fail( __FILE__, __LINE__, "PAPI_reset_event() failed\n", ret);
         }

         ret = PAPI_stop(EventSet, values);                          // stop counting, get final values.
         if (ret != PAPI_OK) {                                       // If that failed, report it.
            free(values);
            test_fail( __FILE__, __LINE__, "PAPI_stop_event(EventSet, values) failed.\n", ret);
         }

         free(values);                                               // free alloc memory.
         values = NULL;                                              // prevent double free.

         ret = PAPI_cleanup_eventset(EventSet);                      // Try a cleanup.
         if (ret != PAPI_OK) {                                       // If that failed, report it.
            test_fail( __FILE__, __LINE__, "PAPI_cleanup_eventset(EventSet) failed.\n", ret);
         }

         ret = PAPI_destroy_eventset(&EventSet);                           // Deallocate. No memory leaks!
         if (ret != PAPI_OK) {                                       // If that failed, report it.
            test_fail( __FILE__, __LINE__, "PAPI_destroy_eventset(EventSet) failed.\n", ret);
         }

         firstTime = 0;                                              // Don't test the one-time functions again.

      } while(PAPI_enum_cmp_event(&k,PAPI_NTV_ENUM_UMASKS,cid)==PAPI_OK);  // Get next umask entry (bits different) (should return PAPI_NOEVNT).
   } while(PAPI_enum_cmp_event(&m,PAPI_ENUM_EVENTS,cid)==PAPI_OK);         // Get next event code.

   // Round 2: Try to load all events into one Event Set.

   // Create an event set.
   ret = PAPI_create_eventset(&EventSet);                            // Try it.
   if (ret != PAPI_OK) {                                             // If that failed, report and exit.
   test_fail(__FILE__, __LINE__, "PAPI_enum_create_eventset failed.\n", ret);
   }

   m=PAPI_NATIVE_MASK;                                               // Get the PAPI NATIVE mask.
   ret=PAPI_enum_cmp_event(&m,PAPI_ENUM_FIRST,cid);                  // Begin enumeration of ALL papi counters.
   if (ret != PAPI_OK) {                                             // If that failed, report and exit.
      test_fail(__FILE__, __LINE__, "PAPI_enum_cmp_event failed.\n",
         ret);
   }

   i = 0;                                                            // To count successful adds.
   do{                                                               // Enumerate all events.
      memset(&info,0,sizeof(PAPI_event_info_t));                     // Clear event info.
      ret=PAPI_get_event_info(m,&info);                              // get name of k symbol.
      if (ret != PAPI_OK) {                                          // If that failed, report and exit.
         retlen = snprintf(errMsg, PAPI_MAX_STR_LEN, "PAPI_get_event_info(%i) failed.\n", k);    // build message.
         if (retlen <= 0 || PAPI_MAX_STR_LEN <= retlen)
              continue;
         test_fail(__FILE__, __LINE__, errMsg, ret);
      }

      // Add it in by name.
      ret=PAPI_add_named_event(EventSet,info.symbol);                // Try to add it for counting.
      if (ret != PAPI_OK) {                                          // If that failed, report it.
         retlen = snprintf(errMsg, PAPI_MAX_STR_LEN, "PAPI_add_named_event('%s') failed.\n", info.symbol);
         if (retlen <= 0 || PAPI_MAX_STR_LEN <= retlen)
            continue;
         test_fail( __FILE__, __LINE__, errMsg, ret);
      } else {
         i++;                                                        // success.
      }
   } while(PAPI_enum_cmp_event(&m,PAPI_ENUM_EVENTS,cid)==PAPI_OK);   // Get next event code.


   if (i != count) {                                                 // If we failed to add them all,
      sprintf(errMsg, "Test should have been able to add all %i events; failed after %i.\n", count, i);    // build message.
      test_fail(__FILE__, __LINE__, errMsg, 0);
   }      

   ret = PAPI_cleanup_eventset(EventSet);                            // Try a cleanup.
   if (ret != PAPI_OK) {                                             // If that failed, report it.
      test_fail( __FILE__, __LINE__, "PAPI_cleanup_eventset(EventSet) failed.\n", ret);
   }

   ret = PAPI_destroy_eventset(&EventSet);                           // Deallocate. No memory leaks!
   if (ret != PAPI_OK) {                                             // If that failed, report it.
      test_fail( __FILE__, __LINE__, "PAPI_destroy_eventset(EventSet) failed.\n", ret);
   }

   if (!quiet) fprintf(stderr, "PCP discovered %i events; added "    // Say what we learned.
               "%i.\n", count, i);                                   // .. 
   PAPI_shutdown();                                                  // get out of papi.
	if (!quiet) fprintf(stderr, "Shutdown completed.\n");             // If we are verbose, 
	test_pass( __FILE__ );                                            // Note the test passed. 
   return 0;                                                         // Exit with all okay.
} // END main.

//-----------------------------------------------------------------------------
// There are four files involved in bench testing. These are 
// Makefile2                     To build executables benchPCP and benchTest. 
// benchPCP_script.sh            To run benchPCP repeatedly, and output a file
//                               of many runs for statistical analysis.
// benchPCP.c                    A program that times the reading of events.
// benchStats.c                  A program to compose statistics on the output
//                               of benchPCP_script.h and output them. 
//
// Usage: 
// You must have installed PAPI with PCP, and have a system with the PCP
// daemon present. 
// 
// In our test system we run on a cluster that uses job-scheduling software;
// specifically 'bsub' and 'jsrun' to request resources then submit a job to be
// run on the cluster. Users may have other methods. The largest distinction
// for us is that we can compile and run shell scripts and code without using
// jsrun; but jsrun is required to run on a node supporting PCP.
// 
// In the file papi/src/component/pcp/linux-pcp.c, we restrict the PCP events
// to a subset; but this can be modified and papi reinstalled to give greater
// access. 

//-----------------------------------------------------------------------------
// benchPCP will time an event (PCP or otherwise) and the time it takes to do
// PAPI_library_init(). Particularly for PCP, it requires a dynamic link
// library (DLL) to run; and the first time such a library is referenced the
// system takes time to load it. This time won't appear for subsequent
// accesses, even though they are different program runs or script runs (the
// DLL is cached). This extra time is evident in the first benchPCP execution,
// but only if the shell is 'fresh'.  We make no attempt to unload the DLL.
// benchPCP produces a heading if invoked with no arguments, or times the
// intialization and the reads and reports those. It takes two arguments; the
// first is an integer for how many reads to average to get an accurate
// per-read timing (100 is typical), and the second is the event name to read.  
//
// Although benchPCP reads the events, it does nothing with the results. The
// only point is to time the reads.  

//-----------------------------------------------------------------------------
// The shell script benchPCP_script.sh SHOULD BE EDITED. It contains its own
// controls internally; for example:
// COUNT=500 # Number of experiments to do.
// READS=100 # Number of times to read the value.
// EVENT_NAME="perfevent.active"
// OUTFILE="benchPCP_test_peactive.csv"
// 
// This instructs the script to execute ./benchPCP 'COUNT' times (500 above),
// and put all the output if these runs into 'OUTFILE', which will be a CSV
// formatted file, with a title row. Each data line of this file will hold
// two timing values, in microseconds (uS): The time required to initialize
// the PAPI system (and all components present), and then the average time
// required to collect a value for the event 'EVENT_NAME' (above this is 
// "perfevent.active"), 'READS' times in a row (above this is 100).
//
// Thus the following plan:
// 1) start microsecond timer,
// 2) for (i=0; i<READS; i++) { PAPI_read(EVENT_NAME, &value); }
// 3) stop microsecond timer.
// 4) compute and report (timeElapsed / READS).
//
// An example output: 
// Initialize, Event Read Avg uS
// 177544.0,   1094.5
// 168264.0,   1099.9
// etc, 'COUNT' data lines, each a single run of benchPCP
// 
// The first line says PAPI_library_init() took 177,544 us (177.5 ms), and 
// the reads of EVENT_NAME took ON AVERAGE 1094.5 us per read. 
// 
// The user can visually inspect the file, or read it into a spreadsheet for
// statistical manipulations, sorting, or graphing. Outlier data lines can be
// deleted from the file without harm. This is the format expected by
// benchStats, the next program to be described.
//
//-----------------------------------------------------------------------------
// benchStats will produce a display of statistics on statistics the authors
// find useful in characterizing the performance of PAPI and PCP. One report
// for each column is reported.
// 
// Usage: ./benchStats filename.csv
// It requires only one argument, the output of benchPCP_script.sh.  It will
// produce the following statistics, once for each column; the following are
// redirected stdout to a file (it will not include the '// ' leader).
// 
//-----------------------------------------------------------------------------
//  
// Stats for Initialization time in file 'benchPCP_test_perfevent.csv'.
// Sample Values                  ,     500
// Minimum uS                     ,160156.0
// Maximum uS                     ,193629.0
// Average uS                     ,172860.8
// Median  uS                     ,175086.0
// First   uS                     ,177544.0
// Max w/o First                  ,193629.0
// Range   uS                     , 33473.0
// Histogram Bins chosen          ,      23
// Bin width uS                   ,  1456.0
// Mode (center highest Bin Count),178356.0
// Mode Bin Count                 ,     121
// Bin Expected Count             ,      22
// 
// Initialization Histogram:
// binCenter, Count, % of Count
// 160884.0,       30, = 6.00%
// 162340.0,       31, = 6.20%
// 163796.0,       59, =11.80%
// 165252.0,       19, = 3.80%
// 166708.0,       13, = 2.60%
// 168164.0,       12, = 2.40%
// 169620.0,       11, = 2.20%
// 171076.0,       17, = 3.40%
// 172532.0,       28, = 5.60%
// 173988.0,       25, = 5.00%
// 175444.0,       22, = 4.40%
// 176900.0,       33, = 6.60%
// 178356.0,      121, =24.20%
// 179812.0,       41, = 8.20%
// 181268.0,       21, = 4.20%
// 182724.0,        7, = 1.40%
// 184180.0,        1, = 0.20%
// 185636.0,        0, = 0.00%
// 187092.0,        2, = 0.40%
// 188548.0,        1, = 0.20%
// 190004.0,        3, = 0.60%
// 191460.0,        1, = 0.20%
// 192916.0,        2, = 0.40%
// 
// Stats for PCP event read time in file 'benchPCP_test_perfevent.csv'.
// Sample Values                  ,     500
// Minimum uS                     ,  1042.5
// Maximum uS                     ,  2365.7
// Average uS                     ,  1384.0
// Median  uS                     ,  1426.8
// First   uS                     ,  1094.5
// Max w/o First                  ,  2365.7
// Range   uS                     ,  1323.2
// Histogram Bins chosen          ,      23
// Bin width uS                   ,    58.0
// Mode (center highest Bin Count),  1419.5
// Mode Bin Count                 ,     218
// Bin Expected Count             ,      22
// 
// Read Event Histogram:
// binCenter, Count, % of Count
//   1071.5,       51, =10.20%
//   1129.5,       20, = 4.00%
//   1187.5,       21, = 4.20%
//   1245.5,        4, = 0.80%
//   1303.5,        0, = 0.00%
//   1361.5,        0, = 0.00%
//   1419.5,      218, =43.60%
//   1477.5,      184, =36.80%
//   1535.5,        0, = 0.00%
//   1593.5,        0, = 0.00%
//   1651.5,        0, = 0.00%
//   1709.5,        0, = 0.00%
//   1767.5,        0, = 0.00%
//   1825.5,        0, = 0.00%
//   1883.5,        0, = 0.00%
//   1941.5,        1, = 0.20%
//   1999.5,        0, = 0.00%
//   2057.5,        0, = 0.00%
//   2115.5,        0, = 0.00%
//   2173.5,        0, = 0.00%
//   2231.5,        0, = 0.00%
//   2289.5,        0, = 0.00%
//   2347.5,        1, = 0.20%
// 
//-----------------------------------------------------------------------------
// Discussion.
// All of these measures are prone to distortion by "weather" in the computing
// environment; meaning the particular mix of other code running, their
// priorities and use of common resources. Such noise can produce outliers,
// particularly on the high end. In general for computing environments, the
// Minimum (barring program failure) has the smallest noise component. 
// 
// Minimum and Maximum are self-explanatory.  The difference between them is
// computed as the Range (reported); a particularly wide range (e.g. more than
// half the Minimum) indicates either an extreme Maximum, or a general high
// noise environment, which may happen on a heavily used cluster.
// 
// Average and Median. These are two measures of centrality. If the
// distribution of values is not skewed, they are the same. The median is the
// most statistically robust measure, it is the 50/50 point; there is a 50%
// chance a measure falls beneath it, and 50% chance it exceeds it. 
//
// However, most distributions ARE skewed. If the Average is LESS than the
// Median, this indicates a skew left, which in turn means the left tail of the
// distribution is more drawn out than the right tail.
// 
// If the Average is MORE than the Median, this means the opposite, the left
// tail is less drawn out than the right tail. That can be caused by a few
// extreme high end samples, or even just one outlier. Unlike the median, if we
// had hundreds of values in the [1000, 1200] range, but a single outlier
// sample of 1,000,000, we could see a Median of 1100, but an average of 3100:
// Given 500 samples, that (1,000,000 / 500)=2000 added to the average all by
// itself. This is why the median is called "robust", it is completely immune
// to the magnitude of outliers.
// 
// First, Max w/o First: This lets us isolate system-wide one-time costs. In
// particular, when PAPI is configured with the PCP component, the execution of
// PAPI_library_init() must also initialize communications with PCP. This
// requires code residing in a DLL (Dynamic Link Library) provided with PCP.
// The very first time in a new shell, it takes some time for the OS to find
// and load the PCP DLL, but then it is cached and this cost is avoided for any
// subsequent PAPI_library_init() executions. However, after loading the DLL,
// there is more work to be done; the component retrieves information from PCP
// about what events it can provide and then translate and provide that
// information to PAPI, so PAPI can use them.  Because of the DLL, the very
// first Initialization cost MIGHT be many milliseconds longer than the
// subsequent Initialization costs. So we provide both the Maximum overall, and
// the Maximum without considering the first Dataline in the file, and we
// provide the first as well. The difference between the First and Maximum w/o
// First, if positive and large, can provide an estimated cost of finding,
// loading and caching the PCP DLL. If that difference is not significant, the
// DLL was likely already cached when the first benchPCP executed.
// 
// Histogram: Internally we construct a histogram to identify an empirical
// major mode. We show the numeric version of that here. 
// 
// Histogram Bins chosen: The number of bins. This is set as the square root of
// the count, rounded up to the next integer. Above, sqrt(500) ~ 22.36, so the
// number of bins is 23.0.
//
// If the distribution of times is uniform, then all the bins would have the
// same count. Since the number of bins is the sqrt(Count), the number per bin
// is Count/sqrt(Count) = sqrt(Count), also. That is in Bin Expected Count; in
// the both cases above it is one less than the number of bins due to rounding.
// 
// If we made many MORE bins, they would be narrower and the expected count
// would be lower. Too many, and it becomes difficult to see the shape of the
// distribution; eventually each sample is likely the only resident in its bin
// and we see nothing. If we made FEWER bins, we would have higher counts in
// each, but the width of bins would be wider and thus less accurate in what
// they tell us about the distribution. Again, eventually we have one bin with
// all the samples in it! Here we choose bins and counts to be nearly the same;
// that is the balancing act between accuracy (narrow bin widths) and shape,
// having enough bins to have a diversity of counts. There is no definitive
// answer to computing an ideal bin width; it is the topic of several studies.
//
// Bin width is the Range (max - min) divided by the number of bins and rounded
// up to the next integer. For the Installation histogram above, the Bin width
// is 1456 uS. For the Read Event, the Bin width is 58.0 uS.
//
// We distribute the values into the bins we created. We find the bin with the
// most values in it, and that is the Mode.  We report in "Mode Bin Count" the
// number of samples that fell into that bin, so you can compare it to the Bin
// Expected Count from above. The Mode is the center of the range, there is
// half the Bin width on either side of it. This is a third measure of
// centrality, the highest count bin is the most likely bin for such a
// measurement to land in. The closer the Mode Bin Count is to the Bin Expected
// Value, the more uniform (flatter) your distribution. You can be sure of that
// by looking at the histogram percentages.
//
// MULTI_MODAL distributions: Some histograms will have more than one peak; on
// both of the examples above, there are two peaks. If this does not go away
// with more samples, it is a sign that the computing environment has distinct
// 'modes', i.e. the environment changes periodically so the histogram
// represents a mashup of multiple normal distributions. That could be other
// user code running, OS functions running, task switching, code migration,
// swapping, paging, etc.  
//
// How to use all this info: You will pay the one-time cost of initializing PCP
// to use PCP, and the Read Event costs each time you read an event. If you are
// doing either of these many times, you should estimate that cost as one of
// the measures of centrality; the average, median, or mode; to be conservative
// take the highest of those.

