static
int check_pmmr(void)
{
	uint64_t pmmr;
	asm volatile(
		"smir %0, %pmmr":"=r"(pmmr));
	if (pmmr != 0x0000000000001000) {
		fprintf(stderr, "PMMR is not expected: 0x%lx\n", pmmr);
		return -1;
	}
    return PAPI_OK;
}

