static int
_papi_pfnec_read( hwd_context_t * ctx, hwd_control_state_t * ctl,
				long long **events, int flags )
{
	uint64_t pmc[16];
	asm volatile(
		"smir %0,%pmc00\n"
		"smir %1,%pmc01\n"
		"smir %2,%pmc02\n"
		"smir %3,%pmc03\n"
		"smir %4,%pmc04\n"
		"smir %5,%pmc05\n"
		"smir %6,%pmc06\n"
		"smir %7,%pmc07\n"
		"smir %8,%pmc08\n"
		"smir %9,%pmc09\n"
		"smir %10,%pmc10\n"
		"smir %11,%pmc11\n"
		"smir %12,%pmc12\n"
		"smir %13,%pmc13\n"
		"smir %14,%pmc14\n"
		"smir %15,%pmc15\n"
		:"=r"(pmc[0]),
		 "=r"(pmc[1]),
		 "=r"(pmc[2]),
		 "=r"(pmc[3]),
		 "=r"(pmc[4]),
		 "=r"(pmc[5]),
		 "=r"(pmc[6]),
		 "=r"(pmc[7]),
		 "=r"(pmc[8]),
		 "=r"(pmc[9]),
		 "=r"(pmc[10]),
		 "=r"(pmc[11]),
		 "=r"(pmc[12]),
		 "=r"(pmc[13]),
		 "=r"(pmc[14]),
		 "=r"(pmc[15])
		:);

    (void) flags;
    (void) ctx;
    _perfnec_control_state_t* control = ( _perfnec_control_state_t* ) ctl;

    long long curr_val = 0;

    int c, i;
    for( c = 0; c < control->active_counters; c++ ) {
        i = control->which_counter[c];
        curr_val = pmc[i];
        SUBDBG("%d, current value %lld\n", i, curr_val);
        control->count[c]=curr_val;
    }

    *events = ( ( _perfnec_control_state_t* ) ctl )->count;

    return PAPI_OK;
}

