#ifdef HAVE_ROCM
hsa_status_t
count_devices( hsa_agent_t agent, void *data )
{
    int *count = (int *) data;

    hsa_device_type_t type;
    ROCM_CALL((*hsa_agent_get_infoPtr)(agent, HSA_AGENT_INFO_DEVICE, &type),
              return _status);

    if (type == HSA_DEVICE_TYPE_GPU) {
        ++(*count);
    }

    return HSA_STATUS_SUCCESS;
}

hsa_status_t
get_device_count( int *count )
{
    *count = 0;

    ROCM_CALL((*hsa_iterate_agentsPtr)(&count_devices, count),
              return _status);

    return HSA_STATUS_SUCCESS;
}

hsa_status_t
get_device_memory( hsa_amd_memory_pool_t pool, void *info )
{
    hsa_region_segment_t seg_info;
    _sysdetect_gpu_info_u *dev_info = info;

    ROCM_CALL((*hsa_amd_memory_pool_get_infoPtr)(pool,
                                                 HSA_AMD_MEMORY_POOL_INFO_SEGMENT,
                                                 &seg_info),
              return _status);

    if (seg_info == HSA_REGION_SEGMENT_GROUP) {
        ROCM_CALL((*hsa_amd_memory_pool_get_infoPtr)(pool,
                                                     HSA_AMD_MEMORY_POOL_INFO_SIZE,
                                                     &dev_info->amd.max_shmmem_per_workgroup),
                  return _status);
        return HSA_STATUS_INFO_BREAK;
    }

    return HSA_STATUS_SUCCESS;
}

hsa_status_t
get_device_properties( hsa_agent_t agent, void *info )
{
    static int count;

    hsa_device_type_t type;
    ROCM_CALL((*hsa_agent_get_infoPtr)(agent, HSA_AGENT_INFO_DEVICE, &type),
              return _status);

    if (type == HSA_DEVICE_TYPE_GPU) {
        /* query attributes for this device */
        _sysdetect_gpu_info_u *dev_info = &((_sysdetect_gpu_info_u *) info)[count];

        ROCM_CALL((*hsa_agent_get_infoPtr)(agent,
                                           HSA_AGENT_INFO_NAME,
                                           dev_info->amd.name),
                  return _status);
        ROCM_CALL((*hsa_agent_get_infoPtr)(agent,
                                           HSA_AGENT_INFO_WAVEFRONT_SIZE,
                                           &dev_info->amd.wavefront_size),
                  return _status);
        unsigned short wg_dims[3];
        ROCM_CALL((*hsa_agent_get_infoPtr)(agent,
                                           HSA_AGENT_INFO_WORKGROUP_MAX_DIM,
                                           wg_dims),
                  return _status);
        ROCM_CALL((*hsa_agent_get_infoPtr)(agent,
                                           HSA_AGENT_INFO_WORKGROUP_MAX_SIZE,
                                           &dev_info->amd.max_threads_per_workgroup),
                  return _status);
        hsa_dim3_t gr_dims;
        ROCM_CALL((*hsa_agent_get_infoPtr)(agent,
                                           HSA_AGENT_INFO_GRID_MAX_DIM,
                                           &gr_dims),
                  return _status);
        ROCM_CALL((*hsa_agent_get_infoPtr)(agent,
                                           HSA_AGENT_INFO_VERSION_MAJOR,
                                           &dev_info->amd.major),
                  return _status);
        ROCM_CALL((*hsa_agent_get_infoPtr)(agent,
                                           HSA_AGENT_INFO_VERSION_MINOR,
                                           &dev_info->amd.minor),
                  return _status);
        ROCM_CALL((*hsa_agent_get_infoPtr)(agent, (hsa_agent_info_t)
                                           HSA_AMD_AGENT_INFO_NUM_SIMDS_PER_CU,
                                           &dev_info->amd.simd_per_compute_unit),
                  return _status);
        ROCM_CALL((*hsa_agent_get_infoPtr)(agent, (hsa_agent_info_t)
                                           HSA_AMD_AGENT_INFO_COMPUTE_UNIT_COUNT,
                                           &dev_info->amd.compute_unit_count),
                  return _status);
        ROCM_CALL((*hsa_agent_get_infoPtr)(agent, (hsa_agent_info_t)
                                           HSA_AMD_AGENT_INFO_MAX_WAVES_PER_CU,
                                           &dev_info->amd.max_waves_per_compute_unit),
                  return _status);
        ROCM_CALL((*hsa_amd_agent_iterate_memory_poolsPtr)(agent,
                                                           &get_device_memory,
                                                           dev_info),
                  return _status);

        dev_info->amd.max_workgroup_dim_x = wg_dims[0];
        dev_info->amd.max_workgroup_dim_y = wg_dims[1];
        dev_info->amd.max_workgroup_dim_z = wg_dims[2];
        dev_info->amd.max_grid_dim_x  = gr_dims.x;
        dev_info->amd.max_grid_dim_y  = gr_dims.y;
        dev_info->amd.max_grid_dim_z  = gr_dims.z;

        ++count;
    }

    return HSA_STATUS_SUCCESS;
}

void
fill_dev_info( _sysdetect_gpu_info_u *dev_info )
{
    hsa_status_t status = HSA_STATUS_SUCCESS;
    const char *string = NULL;

    ROCM_CALL((*hsa_iterate_agentsPtr)(&get_device_properties, dev_info),
             status = _status);

    if (status != HSA_STATUS_SUCCESS) {
        (*hsa_status_stringPtr)(status, &string);
        SUBDBG( "error: %s\n", string );
    }
}

int
hsa_is_enabled( void )
{
    return (hsa_initPtr                           != NULL &&
            hsa_shut_downPtr                      != NULL &&
            hsa_iterate_agentsPtr                 != NULL &&
            hsa_agent_get_infoPtr                 != NULL &&
            hsa_amd_agent_iterate_memory_poolsPtr != NULL &&
            hsa_amd_memory_pool_get_infoPtr       != NULL &&
            hsa_status_stringPtr                  != NULL);
}

int
load_hsa_sym( char *status )
{
    char pathname[PATH_MAX] = "libhsa-runtime64.so";
    char *rocm_root = getenv("PAPI_ROCM_ROOT");
    if (rocm_root != NULL) {
        sprintf(pathname, "%s/lib/libhsa-runtime64.so", rocm_root);
    }

    rocm_dlp = dlopen(pathname, RTLD_NOW | RTLD_GLOBAL);
    if (rocm_dlp == NULL) {
        int count = snprintf(status, PAPI_MAX_STR_LEN, "%s", dlerror());
        if (count >= PAPI_MAX_STR_LEN) {
            SUBDBG("Status string truncated.");
        }
        return -1;
    }

    hsa_initPtr                           = dlsym(rocm_dlp, "hsa_init");
    hsa_shut_downPtr                      = dlsym(rocm_dlp, "hsa_shut_down");
    hsa_iterate_agentsPtr                 = dlsym(rocm_dlp, "hsa_iterate_agents");
    hsa_agent_get_infoPtr                 = dlsym(rocm_dlp, "hsa_agent_get_info");
    hsa_amd_agent_iterate_memory_poolsPtr = dlsym(rocm_dlp, "hsa_amd_agent_iterate_memory_pools");
    hsa_amd_memory_pool_get_infoPtr       = dlsym(rocm_dlp, "hsa_amd_memory_pool_get_info");
    hsa_status_stringPtr                  = dlsym(rocm_dlp, "hsa_status_string");

    if (!hsa_is_enabled() || (*hsa_initPtr)()) {
        const char *message = "dlsym() of HSA symbols failed or hsa_init() "
                              "failed";
        int count = snprintf(status, PAPI_MAX_STR_LEN, "%s", message);
        if (count >= PAPI_MAX_STR_LEN) {
            SUBDBG("Status string truncated.");
        }
        return -1;
    }

    return 0;
}

int
unload_hsa_sym( void )
{
    if (rocm_dlp != NULL) {
        (*hsa_shut_downPtr)();
        dlclose(rocm_dlp);
    }

    hsa_initPtr                           = NULL;
    hsa_shut_downPtr                      = NULL;
    hsa_iterate_agentsPtr                 = NULL;
    hsa_agent_get_infoPtr                 = NULL;
    hsa_amd_agent_iterate_memory_poolsPtr = NULL;
    hsa_amd_memory_pool_get_infoPtr       = NULL;
    hsa_status_stringPtr                  = NULL;

    return hsa_is_enabled();
}
#endif /* HAVE_ROCM */

#ifdef HAVE_ROCM_SMI
void
fill_dev_affinity_info( _sysdetect_gpu_info_u *info, int dev_count )
{
    int dev;
    for (dev = 0; dev < dev_count; ++dev) {
        unsigned long uid;
        ROCM_SMI_CALL((*rsmi_dev_pci_id_getPtr)(dev, &uid), return);

        _sysdetect_gpu_info_u *dev_info = &info[dev];
        dev_info->amd.uid = uid;
    }
}

int
rsmi_is_enabled( void )
{
    return (rsmi_initPtr           != NULL &&
            rsmi_shut_downPtr      != NULL &&
            rsmi_dev_pci_id_getPtr != NULL);
}

int
load_rsmi_sym( char *status )
{
    char pathname[PATH_MAX] = "librocm_smi64.so";
    char *rsmi_root = getenv("PAPI_ROCM_ROOT");
    if (rsmi_root != NULL) {
        sprintf(pathname, "%s/lib/librocm_smi64.so", rsmi_root);
    }

    rsmi_dlp = dlopen(pathname, RTLD_NOW | RTLD_GLOBAL);
    if (rsmi_dlp == NULL) {
        int count = snprintf(status, PAPI_MAX_STR_LEN, "%s", dlerror());
        if (count >= PAPI_MAX_STR_LEN) {
            SUBDBG("Status string truncated.");
        }
        return -1;
    }

    rsmi_initPtr           = dlsym(rsmi_dlp, "rsmi_init");
    rsmi_shut_downPtr      = dlsym(rsmi_dlp, "rsmi_shut_down");
    rsmi_dev_pci_id_getPtr = dlsym(rsmi_dlp, "rsmi_dev_pci_id_get");

    if (!rsmi_is_enabled() || (*rsmi_initPtr)(0)) {
        const char *message = "dlsym() of RSMI symbols failed or rsmi_init() "
                              "failed";
        int count = snprintf(status, PAPI_MAX_STR_LEN, "%s", message);
        if (count >= PAPI_MAX_STR_LEN) {
            SUBDBG("Status string truncated.");
        }
        return -1;
    }

    return 0;
}

int
unload_rsmi_sym( void )
{
    if (rsmi_dlp != NULL) {
        (*rsmi_shut_downPtr)();
        dlclose(rsmi_dlp);
    }

    rsmi_initPtr           = NULL;
    rsmi_shut_downPtr      = NULL;
    rsmi_dev_pci_id_getPtr = NULL;

    return rsmi_is_enabled();
}
#endif /* HAVE_ROCM_SMI */

void
open_amd_gpu_dev_type( _sysdetect_dev_type_info_t *dev_type_info )
{
    memset(dev_type_info, 0, sizeof(*dev_type_info));
    dev_type_info->id = PAPI_DEV_TYPE_ID__ROCM;
    strcpy(dev_type_info->vendor, "AMD/ATI");
    strcpy(dev_type_info->status, "Device Initialized");

#ifdef HAVE_ROCM
    if (load_hsa_sym(dev_type_info->status)) {
        return;
    }

    int dev_count = 0;
    hsa_status_t status = get_device_count(&dev_count);
    if (status != HSA_STATUS_SUCCESS) {
        if (status != HSA_STATUS_ERROR_NOT_INITIALIZED) {
            const char *string;
            (*hsa_status_stringPtr)(status, &string);
            printf( "error: %s\n", string );
        }
        return;
    }
    dev_type_info->num_devices = dev_count;

    _sysdetect_gpu_info_u *arr = papi_calloc(dev_count, sizeof(*arr));
    fill_dev_info(arr);

#ifdef HAVE_ROCM_SMI
    if (!load_rsmi_sym(dev_type_info->status)) {
        fill_dev_affinity_info(arr, dev_count);
        unload_rsmi_sym();
    }
#else
    const char *message = "RSMI not configured, no device affinity available";
    int count = snprintf(dev_type_info->status, PAPI_MAX_STR_LEN, "%s", message);
    if (count >= PAPI_MAX_STR_LEN) {
        SUBDBG("Error message truncated.");
    }
#endif /* HAVE_ROCM_SMI */

    unload_hsa_sym();
    dev_type_info->dev_info_arr = (_sysdetect_dev_info_u *)arr;
#else
    const char *message = "ROCm not configured, no ROCm device available";
    int count = snprintf(dev_type_info->status, PAPI_MAX_STR_LEN, "%s", message);
    if (count >= PAPI_MAX_STR_LEN) {
        SUBDBG("Error message truncated.");
    }
#endif /* HAVE_ROCM */
}

void
close_amd_gpu_dev_type( _sysdetect_dev_type_info_t *dev_type_info )
{
    papi_free(dev_type_info->dev_info_arr);
}

/**
* @file    linux-stealtime.c
* @author  Vince Weaver
*          vweaver1@eecs.utk.edu
* @brief A component that gather info on VM stealtime
*/

#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <dirent.h>
#include <stdint.h>
#include <ctype.h>

#include "papi.h"
#include "papi_internal.h"
#include "papi_vector.h"
#include "papi_memory.h"

struct counter_info
{
	char *name;
	char *description;
        char *units;
	unsigned long long value;
};

typedef struct counter_info STEALTIME_register_t;
typedef struct counter_info STEALTIME_native_event_entry_t;
typedef struct counter_info STEALTIME_reg_alloc_t;


struct STEALTIME_control_state
{
  long long *values;
  int *which_counter;
  int num_events;
};


struct STEALTIME_context
{
  long long *start_count;
  long long *current_count;
  long long *value;
};


static int num_events = 0;

static struct counter_info *event_info=NULL;

/* Advance declaration of buffer */
papi_vector_t _stealtime_vector;

/******************************************************************************
 ********  BEGIN FUNCTIONS  USED INTERNALLY SPECIFIC TO THIS COMPONENT ********
 *****************************************************************************/

struct statinfo {
  long long user;
  long long nice;
  long long system;
  long long idle;
  long long iowait;
  long long irq;
  long long softirq;
  long long steal;
  long long guest;
};

static int
read_stealtime( struct STEALTIME_context *context, int starting) {

  FILE *fff;
  char buffer[BUFSIZ],*result;
  int i,count;
  struct statinfo our_stat;

  int hz=sysconf(_SC_CLK_TCK);


  fff=fopen("/proc/stat","r");
  if (fff==NULL) {
     return PAPI_ESYS; 
  }

  for(i=0;i<num_events;i++) {
    result=fgets(buffer,BUFSIZ,fff);
    if (result==NULL) break;

    count=sscanf(buffer,"%*s %lld %lld %lld %lld %lld %lld %lld %lld %lld",
		 &our_stat.user,
		 &our_stat.nice,
		 &our_stat.system,
		 &our_stat.idle,
		 &our_stat.iowait,
		 &our_stat.irq,
		 &our_stat.softirq,
		 &our_stat.steal,
		 &our_stat.guest);
    if (count<=7) {
       fclose(fff);
       return PAPI_ESYS;
    }

    if (starting) {
       context->start_count[i]=our_stat.steal;
    }
    context->current_count[i]=our_stat.steal;

    /* convert to us */
    context->value[i]=(context->current_count[i]-context->start_count[i])*
      (1000000/hz);
  }


  fclose(fff);

  return PAPI_OK;

}



/*****************************************************************************
 *******************  BEGIN PAPI's COMPONENT REQUIRED FUNCTIONS  *************
 *****************************************************************************/

/*
 * Component setup and shutdown
 */
static int _stealtime_shutdown_component( void );  // prototype for later routine.

static int
_stealtime_init_component( int cidx )
{
    int retval = PAPI_OK;
  (void)cidx;

	FILE *fff;
	char buffer[BUFSIZ],*result,string[BUFSIZ];
	int i;

	/* Make sure /proc/stat exists */
	fff=fopen("/proc/stat","r");
	if (fff==NULL) {
	   strncpy(_stealtime_vector.cmp_info.disabled_reason,
		   "Cannot open /proc/stat",PAPI_MAX_STR_LEN);
       _stealtime_shutdown_component();
       retval = PAPI_ESYS;
       goto fn_fail;
	}

	num_events=0;
	while(1) {
	  result=fgets(buffer,BUFSIZ,fff);
	  if (result==NULL) break;

	  /* /proc/stat line with cpu stats always starts with "cpu" */

	  if (!strncmp(buffer,"cpu",3)) {
	     num_events++;
	  }
	  else {
	    break;
	  }

	}

	fclose(fff);

	if (num_events<1) {
	   strncpy(_stealtime_vector.cmp_info.disabled_reason,
		   "Cannot find enough CPU lines in /proc/stat",
		   PAPI_MAX_STR_LEN);
       _stealtime_shutdown_component();
       retval = PAPI_ESYS;
       goto fn_fail;
	}

	event_info=calloc(num_events,sizeof(struct counter_info));
	if (event_info==NULL) {
        _stealtime_shutdown_component();
        retval = PAPI_ENOMEM;
        goto fn_fail;
	}


	sysconf(_SC_CLK_TCK);
	event_info[0].name=strdup("TOTAL");
	event_info[0].description=strdup("Total amount of steal time");
	event_info[0].units=strdup("us");

	for(i=1;i<num_events;i++) {
	   sprintf(string,"CPU%d",i);
	   event_info[i].name=strdup(string);
	   sprintf(string,"Steal time for CPU %d",i);
	   event_info[i].description=strdup(string);
	   event_info[i].units=strdup("us");
        }

	//	printf("Found %d CPUs\n",num_events-1);

	_stealtime_vector.cmp_info.num_native_events=num_events;
	_stealtime_vector.cmp_info.num_cntrs=num_events;
	_stealtime_vector.cmp_info.num_mpx_cntrs=num_events;

  fn_exit:
    _papi_hwd[cidx]->cmp_info.disabled = retval;
    return retval;
  fn_fail:
    goto fn_exit;
}





/*
 * This is called whenever a thread is initialized
 */
static int
_stealtime_init_thread( hwd_context_t * ctx )
{
  struct STEALTIME_context *context=(struct STEALTIME_context *)ctx;

  context->start_count=calloc(num_events,sizeof(long long));
  if (context->start_count==NULL) return PAPI_ENOMEM;

  context->current_count=calloc(num_events,sizeof(long long));
  if (context->current_count==NULL) return PAPI_ENOMEM;

  context->value=calloc(num_events,sizeof(long long));
  if (context->value==NULL) return PAPI_ENOMEM;

  return PAPI_OK;
}


/*
 *
 */
static int
_stealtime_shutdown_component( void )
{
       int i;
       int num_events = _stealtime_vector.cmp_info.num_native_events;
       if (event_info!=NULL) {
               for (i=0; i<num_events; i++){
                       free(event_info[i].name);
                       free(event_info[i].description);
                       free(event_info[i].units);
               }
               free(event_info);
       }

   return PAPI_OK;
}

