		unsigned long newent;

		if ( ( flags & PAPI_PROFIL_INST_EAR ) == 0 )
			goto safety;

		/* Skip the header */
		++( *ent );

		// PMD34 has data address on Montecito
		// PMD35 has latency on Montecito
		icache_line_addr = *( pfm_mont_pmd_reg_t * ) * ent;
