typedef struct
{
    int device;                //!< compute device number
    CUcontext context;         //!< CUDA driver context, or NULL if default context has already been initialized
} profilingConfig;

// Per-device configuration, buffers, stream and device information, and device pointers
typedef struct
{
    int deviceID;
    profilingConfig config;                 // Each device (or each context) needs its own CUPTI profiling config
    vector<cudaStream_t> streams;           // Each device needs its own streams
    vector<double *> d_x;                   // And device memory allocation
    vector<double *> d_y;                   // ..
    long long values[100];                  // Capture PAPI measured values for each device
} perDeviceData;

#define DAXPY_REPEAT 32768
// Loop over array of elements performing daxpy multiple times
// To be launched with only one block (artificially increasing serial time to better demonstrate overlapping replay)
__global__ void daxpyKernel(int elements, double a, double * x, double * y)
{
    for (int i = threadIdx.x; i < elements; i += blockDim.x)
        // Artificially increase kernel runtime to emphasize concurrency
        for (int j = 0; j < DAXPY_REPEAT; j++)
            y[i] = a * x[i] + y[i]; // daxpy
}

// Initialize kernel values
double a = 2.5;

// Normally you would want multiple warps, but to emphasize concurrency with streams and multiple devices
// we run the kernels on a single warp.
int threadsPerBlock = 32;
int threadBlocks = 1;

// Configurable number of kernels (streams, when running concurrently)
int const numKernels = 4;
int const numStreams = numKernels;
vector<size_t> elements(numKernels);

// Each kernel call allocates and computes (call number) * (blockSize) elements
// For 4 calls, this is 4k elements * 2 arrays * (1 + 2 + 3 + 4 stream mul) * 8B/elem =~ 640KB
int const blockSize = 4 * 1024;

// Globals for successfully added and multiple pass events
int numMultipassEvents = 0;
vector<string> eventsSuccessfullyAdded;

/** @class add_events_from_command_line
  * @brief Try and add each event provided on the command line by the user.
  *
  * @param d
  *   Per device data.
  * @param EventSet
  *   A PAPI eventset.
  * @param metricNames
  *   Events provided on the command line.
  * @param successfullyAddedEvents
  *   Events successfully added to the EventSet.
  * @param *numMultipassEvents
  *   Counter to see if a multiple pass event was provided on the command line.
*/
static void add_events_from_command_line(perDeviceData &d, int EventSet, vector<string> const &metricNames, vector<string> successfullyAddedEvents, int *numMultipassEvents)
{
    int i;
    for (i = 0; i < metricNames.size(); i++) {
        string evt_name = metricNames[i] + std::to_string(d.config.device);
        int papi_errno = PAPI_add_named_event(EventSet, evt_name.c_str());
        if (papi_errno != PAPI_OK) {
            if (papi_errno != PAPI_EMULPASS) {
                fprintf(stderr, "Unable to add event %s to the EventSet with error code %d.\n", evt_name.c_str(), papi_errno);
                test_skip(__FILE__, __LINE__, "", 0);
            }

            // Handle multiple pass events
            (*numMultipassEvents)++;
            continue;
        }

        // Handle successfully added events
        if (find(eventsSuccessfullyAdded.begin(), eventsSuccessfullyAdded.end(), metricNames[i]) == eventsSuccessfullyAdded.end()) {
            eventsSuccessfullyAdded.push_back(metricNames[i]);
        }
    }

    return;
}

// Wrapper which will launch numKernel kernel calls on a single device
// The device streams vector is used to control which stream each call is made on
// If 'serial' is non-zero, the device streams are ignored and instead the default stream is used
void profileKernels(perDeviceData &d,
                    vector<string> const &metricNames,
                    char const * const rangeName, bool serial)
{
    // Switch to desired device
    RUNTIME_API_CALL(cudaSetDevice(d.config.device));  // Orig code has mistake here
    DRIVER_API_CALL(cuCtxSetCurrent(d.config.context));
#ifdef PAPI
    int eventset = PAPI_NULL;
    PAPI_CALL(PAPI_create_eventset(&eventset));

    add_events_from_command_line(d, eventset, metricNames, eventsSuccessfullyAdded, &numMultipassEvents);

    // Only multiple pass events were provided on the command line
    if (eventsSuccessfullyAdded.size() == 0) {
        fprintf(stderr, "Events provided on the command line could not be added to an EventSet as they require multiple passes.\n");
        test_skip(__FILE__, __LINE__, "", 0);
    }

    PAPI_CALL(PAPI_start(eventset));
#endif

    for (unsigned int stream = 0; stream < d.streams.size(); stream++)
    {
        cudaStream_t streamId = (serial ? 0 : d.streams[stream]);
        daxpyKernel <<<threadBlocks, threadsPerBlock, 0, streamId>>> (elements[stream], a, d.d_x[stream], d.d_y[stream]);
    }

    // After launching all work, synchronize all streams
    if (serial == false)
    {
        for (unsigned int stream = 0; stream < d.streams.size(); stream++)
        {
            RUNTIME_API_CALL(cudaStreamSynchronize(d.streams[stream]));
        }
    }
    else
    {
        RUNTIME_API_CALL(cudaStreamSynchronize(0));
    }
#ifdef PAPI
    PAPI_CALL(PAPI_stop(eventset, d.values));
    PAPI_CALL(PAPI_cleanup_eventset(eventset));
    PAPI_CALL(PAPI_destroy_eventset(&eventset));
#endif
}

void print_measured_values(perDeviceData &d, vector<string> const &metricNames)
{
    string evt_name;
    PRINT(quiet, "PAPI event name\t\t\t\t\t\t\tMeasured value\n");
    PRINT(quiet, "%s\n", std::string(80, '-').c_str());
    for (int i=0; i < metricNames.size(); i++) {
        evt_name = metricNames[i] + std::to_string(d.config.device);
        PRINT(quiet, "%s\t\t\t%lld\n", evt_name.c_str(), d.values[i]);
    }
}

int main(int argc, char **argv)
{
    quiet = 0;
    int i;
#ifdef PAPI
    char *test_quiet = getenv("PAPI_CUDA_TEST_QUIET");
    if (test_quiet)
        quiet = (int) strtol(test_quiet, (char**) NULL, 10);

    int event_count = argc - 1;
    /* if no events passed at command line, just report test skipped. */
    if (event_count == 0) {
        fprintf(stderr, "No eventnames specified at command line.\n");
        test_skip(__FILE__, __LINE__, "", 0);
    }

    vector<string> metricNames;
    for (i=0; i < event_count; i++) {
        metricNames.push_back(argv[i+1]);
    }

    // Initialize the PAPI library
    if (PAPI_library_init(PAPI_VER_CURRENT) != PAPI_VER_CURRENT) {
        test_fail(__FILE__, __LINE__, "PAPI_library_init failed.", 0);
    }
#else
    vector<string> metricNames = {""};
#endif

    int numDevices;
    RUNTIME_API_CALL(cudaGetDeviceCount(&numDevices));

    // Per-device information
    vector<int> device_ids;

    // Find all devices capable of running CUPTI Profiling (Compute Capability >= 7.0)
    for (i = 0; i < numDevices; i++)
    {
        // Get device properties
        int major;
        RUNTIME_API_CALL(cudaDeviceGetAttribute(&major, cudaDevAttrComputeCapabilityMajor, i));
        if (major >= 7)
        {
            // Record device number
            device_ids.push_back(i);
        }
    }

    numDevices = device_ids.size();
    PRINT(quiet, "Found %d compatible devices\n", numDevices);

    // Ensure we found at least one device
    if (numDevices == 0)
    {
        fprintf(stderr, "No devices detected compatible with CUPTI Profiling (Compute Capability >= 7.0)\n");
#ifdef PAPI
        test_skip(__FILE__, __LINE__, "", 0);
#endif
    }

    // Initialize kernel input to some known numbers
    vector<double> h_x(blockSize * numKernels);
    vector<double> h_y(blockSize * numKernels);
    for (size_t i = 0; i < blockSize * numKernels; i++)
    {
        h_x[i] = 1.5 * i;
        h_y[i] = 2.0 * (i - 3000);
    }

    // Initialize a vector of 'default stream' values to demonstrate serialized kernels
    vector<cudaStream_t> defaultStreams(numStreams);
    for (int stream = 0; stream < numStreams; stream++)
    {
        defaultStreams[stream] = 0;
    }

    // Scale per-kernel work by stream number
    for (int stream = 0; stream < numStreams; stream++)
    {
        elements[stream] = blockSize * (stream + 1);
    }

    // For each device, configure profiling, set up buffers, copy kernel data
    vector<perDeviceData> deviceData(numDevices);

    for (int device = 0; device < numDevices; device++)
    {
        int device_id = device_ids[device];
        RUNTIME_API_CALL(cudaSetDevice(device_id));
        PRINT(quiet, "Configuring device %d\n", device_id);
        deviceData[device].deviceID = device_id;

        // Required CUPTI Profiling configuration & initialization
        // Can be done ahead of time or immediately before startSession() call
        // Initialization & configuration images can be generated separately, then passed to later calls
        // For simplicity's sake, in this sample, a single config struct is created per device and passed to each CUPTI Profiler API call
        // For more complex cases, each combination of CUPTI Profiler Session and Config requires additional initialization
        profilingConfig config;
        config.device = device_id;         // Device ID, used to get device name for metrics enumeration
        // config.maxLaunchesPerPass = 1;     // Must be >= maxRangesPerPass.  Set this to the largest count of kernel launches which may be encountered in any Pass in this Session

        // // Device 0 has max of 3 passes; other devices only run one pass in this sample code
        DRIVER_API_CALL(cuCtxCreate(&(config.context), 0, device)); // Either set to a context, or may be NULL if a default context has been created
        deviceData[device].config = config;// Save this device config

        // Initialize CUPTI Profiling structures
        // targetInitProfiling(deviceData[device], metricNames);

        // Per-stream initialization & memory allocation - copy from constant host array to each device array
        deviceData[device].streams.resize(numStreams);
        deviceData[device].d_x.resize(numStreams);
        deviceData[device].d_y.resize(numStreams);
        for (int stream = 0; stream < numStreams; stream++)
        {
            RUNTIME_API_CALL(cudaStreamCreate(&(deviceData[device].streams[stream])));

            // Each kernel does (stream #) * blockSize work on doubles
            size_t size = elements[stream] * sizeof(double);

            RUNTIME_API_CALL(cudaMalloc(&(deviceData[device].d_x[stream]), size));
            MEMORY_ALLOCATION_CALL(deviceData[device].d_x[stream]); // Validate pointer
            RUNTIME_API_CALL(cudaMemcpy(deviceData[device].d_x[stream], h_x.data(), size, cudaMemcpyHostToDevice));

            RUNTIME_API_CALL(cudaMalloc(&(deviceData[device].d_y[stream]), size));
            MEMORY_ALLOCATION_CALL(deviceData[device].d_y[stream]); // Validate pointer
            RUNTIME_API_CALL(cudaMemcpy(deviceData[device].d_y[stream], h_x.data(), size, cudaMemcpyHostToDevice));
        }
    }

    //
    // First version - single device, kernel calls serialized on default stream
    //

    // Use wallclock time to measure performance
    auto begin_time = ::std::chrono::high_resolution_clock::now();

    // Run on first device and use default streams, which run serially
    profileKernels(deviceData[0], metricNames, "single_device_serial", true);

    auto end_time = ::std::chrono::high_resolution_clock::now();
    int elapsed_serial_ms = ::std::chrono::duration_cast<::std::chrono::milliseconds>(end_time - begin_time).count();
    int numBlocks = 0;
    for (int i = 1; i <= numKernels; i++)
    {
        numBlocks += i;
    }
    PRINT(quiet, "It took %d ms on the host to profile %d  kernels in serial.", elapsed_serial_ms, numKernels);

    //
    // Second version - same kernel calls as before on the same device, but now using separate streams for concurrency
    // (Should be limited by the longest running kernel)
    //

    begin_time = ::std::chrono::high_resolution_clock::now();

    // Still only use first device, but this time use its allocated streams for parallelism
    profileKernels(deviceData[0], metricNames, "single_device_async", false);

    end_time = ::std::chrono::high_resolution_clock::now();
    int elapsed_single_device_ms = ::std::chrono::duration_cast<::std::chrono::milliseconds>(end_time - begin_time).count();
    PRINT(quiet, "It took %d ms on the host to profile %d  kernels on a single device on separate streams.", elapsed_single_device_ms, numKernels);
    PRINT(quiet, "--> If the separate stream wallclock time is less than the serial version, the streams were profiling concurrently.\n");

    //
    // Third version - same as the second case, but duplicates the concurrent work across devices to show cross-device concurrency
    // This is done using devices so no serialization is needed between devices
    // (Should have roughly the same wallclock time as second case if the devices have similar performance)
    //

    if (numDevices == 1)
    {
        PRINT(quiet, "Only one compatible device found; skipping the multi-threaded test.\n");
    }
    else
    {
#ifdef PAPI
        int papi_errno = PAPI_thread_init((unsigned long (*)(void)) std::this_thread::get_id);
        if ( papi_errno != PAPI_OK ) {
            test_fail(__FILE__, __LINE__, "Error setting thread id function.\n", papi_errno);
        }
#endif

        PRINT(quiet, "Running on %d devices, one thread per device.\n", numDevices);

        // Time creation of the same multiple streams (on multiple devices, if possible)
        vector<::std::thread> threads;
        begin_time = ::std::chrono::high_resolution_clock::now();

        // Now launch parallel thread work, duplicated on one thread per device
        for (int thread = 0; thread < numDevices; thread++)
        {
            threads.push_back(::std::thread(profileKernels, ::std::ref(deviceData[thread]), metricNames, "multi_device_async", false));
        }

        // Wait for all threads to finish
        for (auto &t: threads)
        {
            t.join();
        }

        // Record time used when launching on multiple devices
        end_time = ::std::chrono::high_resolution_clock::now();
        int elapsed_multiple_device_ms = ::std::chrono::duration_cast<::std::chrono::milliseconds>(end_time - begin_time).count();
        PRINT(quiet, "It took %d ms on the host to profile the same %d kernels on each of the %d devices in parallel\n", elapsed_multiple_device_ms, numKernels, numDevices);
        PRINT(quiet, "--> Wallclock ratio of parallel device launch to single device launch is %f\n", elapsed_multiple_device_ms / (double) elapsed_single_device_ms);
        PRINT(quiet, "--> If the ratio is close to 1, that means there was little overhead to profile in parallel on multiple devices compared to profiling on a single device.\n");
        PRINT(quiet, "--> If the devices have different performance, the ratio may not be close to one, and this should be limited by the slowest device.\n");
    }

    // Free stream memory for each device
    for (int i = 0; i < numDevices; i++)
    {
        for (int j = 0; j < numKernels; j++)
        {
            RUNTIME_API_CALL(cudaFree(deviceData[i].d_x[j]));
            RUNTIME_API_CALL(cudaFree(deviceData[i].d_y[j]));
        }
    }

#ifdef PAPI
    // Display metric values
    PRINT(quiet, "\nMetrics for device #0:\n");
    PRINT(quiet, "Look at the sm__cycles_elapsed.max values for each test.\n");
    PRINT(quiet, "This value represents the time spent on device to run the kernels in each case, and should be longest for the serial range, and roughly equal for the single and multi device concurrent ranges.\n");
    print_measured_values(deviceData[0], eventsSuccessfullyAdded);

    // Only display next device info if needed
    if (numDevices > 1)
    {
        PRINT(quiet, "\nMetrics for the remaining devices only display the multi device async case and should all be similar to the first device's values if the device has similar performance characteristics.\n");
        PRINT(quiet, "If devices have different performance characteristics, the runtime cycles calculation may vary by device.\n");
    }
    for (int i = 1; i < numDevices; i++)
    {
        PRINT(quiet, "\nMetrics for device #%d:\n", i);
        print_measured_values(deviceData[i], eventsSuccessfullyAdded);
    }

    PAPI_shutdown();

    // Output a note that a multiple pass event was provided on the command line
    if (numMultipassEvents > 0) {
        PRINT(quiet, "\033[0;33mNOTE: From the events provided on the command line, an event or events requiring multiple passes was detected and not added to the EventSet. Check your events with utils/papi_native_avail.\n\033[0m");
    }

    test_pass(__FILE__);
#endif
    return 0;
}

/**
 * @file    pthreads.cu
 * @author  Anustuv Pal
 *          anustuv@icl.utk.edu
 */

#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include "gpu_work.h"

#ifdef PAPI
#include <papi.h>
#include "papi_test.h"

#define PAPI_CALL(apiFuncCall)                                          \
do {                                                                           \
    int _status = apiFuncCall;                                         \
    if (_status != PAPI_OK) {                                              \
        fprintf(stderr, "error: function %s failed.", #apiFuncCall);  \
        test_fail(__FILE__, __LINE__, "", _status);  \
    }                                                                          \
} while (0)
#endif

#define PRINT(quiet, format, args...) {if (!quiet) {fprintf(stderr, format, ## args);}}
int quiet;

#define RUNTIME_API_CALL(apiFuncCall)                                          \
do {                                                                           \
    cudaError_t _status = apiFuncCall;                                         \
    if (_status != cudaSuccess) {                                              \
        fprintf(stderr, "%s:%d: error: function %s failed with error %s.\n",   \
                __FILE__, __LINE__, #apiFuncCall, cudaGetErrorString(_status));\
        exit(EXIT_FAILURE);                                                    \
    }                                                                          \
} while (0)

#define DRIVER_API_CALL(apiFuncCall)                                           \
do {                                                                           \
    CUresult _status = apiFuncCall;                                            \
    if (_status != CUDA_SUCCESS) {                                             \
        fprintf(stderr, "%s:%d: error: function %s failed with error %d.\n",   \
                __FILE__, __LINE__, #apiFuncCall, _status);                    \
        exit(EXIT_FAILURE);                                                    \
    }                                                                          \
} while (0)

#define MAX_THREADS (32)

int numGPUs;
int g_event_count;
char **g_evt_names;

static volatile int global_thread_count = 0;
pthread_mutex_t global_mutex;
pthread_t tidarr[MAX_THREADS];
CUcontext cuCtx[MAX_THREADS];
pthread_mutex_t lock;

// Globals for multiple pass events
int numMultipassEvents = 0;

/** @class add_events_from_command_line
  * @brief Try and add each event provided on the command line by the user.
  *
  * @param EventSet
  *   A PAPI eventset.
  * @param totalEventCount
  *   Number of events from the command line.
  * @param **eventNamesFromCommandLine
  *   Events provided on the command line.
  * @param gpu_id
  *   NVIDIA device index.
  * @param *numEventsSuccessfullyAdded
  *   Total number of successfully added events.
  * @param **eventsSuccessfullyAdded
  *   Events that we are able to add to the EventSet.
  * @param *numMultipassEvents
  *   Counter to see if a multiple pass event was provided on the command line.
*/
static void add_events_from_command_line(int EventSet, int totalEventCount, char **eventNamesFromCommandLine, int gpu_id, int *numEventsSuccessfullyAdded, char **eventsSuccessfullyAdded, int *numMultipassEvents)
{
    int i;
    for (i = 0; i < totalEventCount; i++) {
        char tmpEventName[PAPI_MAX_STR_LEN];
        int strLen = snprintf(tmpEventName, PAPI_MAX_STR_LEN, "%s:device=%d", eventNamesFromCommandLine[i], gpu_id);
        if (strLen < 0 || strLen >= PAPI_MAX_STR_LEN) {
            fprintf(stderr, "Failed to fully write event name with appended device qualifier.\n");
            test_skip(__FILE__, __LINE__, "", 0);
        }

        int papi_errno = PAPI_add_named_event(EventSet, tmpEventName);
        if (papi_errno != PAPI_OK) {
            if (papi_errno != PAPI_EMULPASS) {
                fprintf(stderr, "Unable to add event %s to the EventSet with error code %d.\n", tmpEventName, papi_errno);
                test_skip(__FILE__, __LINE__, "", 0);
            }

            // Handle multiple pass events
            (*numMultipassEvents)++;
            continue;
        }

        // Handle successfully added events
        strLen = snprintf(eventsSuccessfullyAdded[(*numEventsSuccessfullyAdded)], PAPI_MAX_STR_LEN, "%s", tmpEventName);
        if (strLen < 0 || strLen >= PAPI_MAX_STR_LEN) {
            fprintf(stderr, "Failed to fully write successfully added event.\n");
            test_skip(__FILE__, __LINE__, "", 0);
        }
        (*numEventsSuccessfullyAdded)++;
    }

    return;
}

void *thread_gpu(void * idx)
{
    int tid = *((int*) idx);
    unsigned long gettid = (unsigned long) pthread_self();

#ifdef PAPI
    int gpuid = tid % numGPUs;
    int i;

    int EventSet = PAPI_NULL;
    long long values[MAX_THREADS];
    PAPI_CALL(PAPI_create_eventset(&EventSet));

    DRIVER_API_CALL(cuCtxSetCurrent(cuCtx[tid]));
    PRINT(quiet, "This is idx %d thread %lu - using GPU %d context %p!\n",
            tid, gettid, gpuid, cuCtx[tid]);

    int numEventsSuccessfullyAdded = 0;
    char **eventsSuccessfullyAdded;
    eventsSuccessfullyAdded = (char **) malloc(g_event_count * sizeof(char *));
    if (eventsSuccessfullyAdded == NULL) {
        fprintf(stderr, "Failed to allocate memory for successfully added events.\n");
        test_skip(__FILE__, __LINE__, "", 0);
    }
    for (i = 0; i < g_event_count; i++) {
        eventsSuccessfullyAdded[i] = (char *) malloc(PAPI_MAX_STR_LEN * sizeof(char));
        if (eventsSuccessfullyAdded[i] == NULL) {
            fprintf(stderr, "Failed to allocate memory for command line argument.\n");
            test_skip(__FILE__, __LINE__, "", 0);
        }
    }

    pthread_mutex_lock(&global_mutex);

    add_events_from_command_line(EventSet, g_event_count, g_evt_names, gpuid, &numEventsSuccessfullyAdded, eventsSuccessfullyAdded, &numMultipassEvents);

    // Only multiple pass events were provided on the command line
    if (numEventsSuccessfullyAdded == 0) {
        fprintf(stderr, "Events provided on the command line could not be added to an EventSet as they require multiple passes.\n");
        test_skip(__FILE__, __LINE__, "", 0);
    }

    ++global_thread_count;
    pthread_mutex_unlock(&global_mutex);

    while(global_thread_count < numGPUs);

    PAPI_CALL(PAPI_start(EventSet));
#endif

    VectorAddSubtract(50000*(tid+1), quiet);  // gpu work

#ifdef PAPI
    PAPI_CALL(PAPI_stop(EventSet, values));

    PRINT(quiet, "User measured values in thread id %d.\n", tid);
    for (i = 0; i < numEventsSuccessfullyAdded; i++) {
        PRINT(quiet, "%s\t\t%lld\n", eventsSuccessfullyAdded[i], values[i]);
    }

    // Free allocated memory
    for (i = 0; i < g_event_count; i++) {
        free(eventsSuccessfullyAdded[i]);
    }
    free(eventsSuccessfullyAdded);

    PAPI_CALL(PAPI_cleanup_eventset(EventSet));
    PAPI_CALL(PAPI_destroy_eventset(&EventSet));
#endif
    return NULL;
}

int main(int argc, char **argv)
{
    quiet = 0;
#ifdef PAPI
    char *test_quiet = getenv("PAPI_CUDA_TEST_QUIET");
    if (test_quiet)
        quiet = (int) strtol(test_quiet, (char**) NULL, 10);

    g_event_count = argc - 1;
    /* if no events passed at command line, just report test skipped. */
    if (g_event_count == 0) {
        fprintf(stderr, "No eventnames specified at command line.\n");
        test_skip(__FILE__, __LINE__, "", 0);
    }
    g_evt_names = argv + 1;
#endif
    int rc, i;
    int tid[MAX_THREADS];

    RUNTIME_API_CALL(cudaGetDeviceCount(&numGPUs));
    PRINT(quiet, "No. of GPUs = %d\n", numGPUs);
    if (numGPUs < 1) {
        fprintf(stderr, "No GPUs found on system.\n");
#ifdef PAPI
        test_skip(__FILE__, __LINE__, "", 0);
#endif
        return 0;
    }
    if (numGPUs > MAX_THREADS)
        numGPUs = MAX_THREADS;
    PRINT(quiet, "No. of threads to launch = %d\n", numGPUs);

#ifdef PAPI
    pthread_mutex_init(&global_mutex, NULL);
    int papi_errno = PAPI_library_init( PAPI_VER_CURRENT );
    if( papi_errno != PAPI_VER_CURRENT ) {
        test_fail(__FILE__, __LINE__, "PAPI_library_init failed.", 0);
    }
    // Point PAPI to function that gets the thread id
    PAPI_CALL(PAPI_thread_init((unsigned long (*)(void)) pthread_self));
#endif
    // Launch the threads
    for(i = 0; i < numGPUs; i++)
    {
        tid[i] = i;
        DRIVER_API_CALL(cuCtxCreate(&(cuCtx[i]), 0, i % numGPUs));
        DRIVER_API_CALL(cuCtxPopCurrent(&(cuCtx[i])));

        rc = pthread_create(&tidarr[i], NULL, thread_gpu, &(tid[i]));
        if(rc)
        {
            fprintf(stderr, "\n ERROR: return code from pthread_create is %d \n", rc);
            exit(1);
        }


        PRINT(quiet, "\n Main thread %lu. Created new thread (%lu) in iteration %d ...\n",
                (unsigned long)pthread_self(), (unsigned long)tidarr[i], i);
    }

    // Join all threads when complete
    for (i = 0; i < numGPUs; i++) {
        pthread_join(tidarr[i], NULL);
        PRINT(quiet, "IDX: %d: TID: %lu: Done! Joined main thread.\n", i, (unsigned long)tidarr[i]);
    }

    // Destroy all CUDA contexts for all threads/GPUs
    for (i = 0; i < numGPUs; i++) {
        DRIVER_API_CALL(cuCtxDestroy(cuCtx[i]));
    }
#ifdef PAPI
    PAPI_shutdown();

    PRINT(quiet, "Main thread exit!\n");

    // Output a note that a multiple pass event was provided on the command line
    if (numMultipassEvents > 0) {
        PRINT(quiet, "\033[0;33mNOTE: From the events provided on the command line, an event or events requiring multiple passes was detected and not added to the EventSet. Check your events with utils/papi_native_avail.\n\033[0m");
    }

    test_pass(__FILE__);
#endif
    return 0;
}

/**
 * @file    test_multipass_event_fail.cu
 * @author  Anustuv Pal
 *          anustuv@icl.utk.edu
 */

#include <stdio.h>

#ifdef PAPI
#include "papi.h"
#include "papi_test.h"

#define PASS 1
#define FAIL 0
#define MAX_EVENT_COUNT (32)
#define PRINT(quiet, format, args...) {if (!quiet) {fprintf(stderr, format, ## args);}}
int quiet;

int test_PAPI_add_named_event(int *EventSet, int numEvents, char **EventName) {
    int i, papi_errno;
    PRINT(quiet, "LOG: %s: Entering.\n", __func__);
    for (i=0; i<numEvents; i++) {
        papi_errno = PAPI_add_named_event(*EventSet, EventName[i]);
        if (papi_errno != PAPI_EMULPASS && papi_errno != PAPI_OK) {
            fprintf(stderr, "Failed to add named event %s with error code %d.\n", EventName[i], papi_errno);
            return FAIL;
        }
    }
    if (papi_errno == PAPI_EMULPASS || papi_errno == PAPI_OK) {
        PRINT(quiet, "PASSED test_PAPI_add_named_event\n");
        return PASS; // Test pass condition
    }
    return FAIL;
}

int test_PAPI_add_event(int *EventSet, int numEvents, char **EventName, int *numEventsSuccessfullyAdded) {
    int event, i, papi_errno;
    PRINT(quiet, "LOG: %s: Entering.\n", __func__);

    for (i=0; i<numEvents; i++) {
        papi_errno = PAPI_event_name_to_code(EventName[i], &event);
        if (papi_errno != PAPI_OK) {
            fprintf(stderr, "Failed to convert event name %s to event code with error code %d.\n", EventName[i], papi_errno);
            goto fail;
        }
        papi_errno = PAPI_add_event(*EventSet, event);
        if (papi_errno != PAPI_OK) {
            if (papi_errno != PAPI_EMULPASS) {
                fprintf(stderr, "Failed to add event %s with error code %d.\n", EventName[i], papi_errno);
                goto fail;
            }
        }
        else {
            (*numEventsSuccessfullyAdded)++;
        }
    }
    if (papi_errno == PAPI_EMULPASS || papi_errno == PAPI_OK) {
        PRINT(quiet, "PASSED test_PAPI_add_event\n");
        return PASS;
    }
fail:
    return FAIL;
}

int test_PAPI_add_events(int *EventSet, int numEvents, char **EventName, int numEventsSuccessfullyAdded) {
    int papi_errno, i;
    PRINT(quiet, "LOG: %s: Entering.\n", __func__);

    int events[MAX_EVENT_COUNT];

    for (i=0; i<numEvents; i++) {
        papi_errno = PAPI_event_name_to_code(EventName[i], &events[i]);
        if (papi_errno != PAPI_OK) {
            fprintf(stderr, "Failed to convert event name %s to event code with error code %d.\n", EventName[i], papi_errno);
            goto fail;
        }
    }
    papi_errno = PAPI_add_events(*EventSet, events, numEvents);
    if (papi_errno == PAPI_EMULPASS || papi_errno == PAPI_OK || papi_errno == numEventsSuccessfullyAdded) {
        PRINT(quiet, "PASSED test_PAPI_add_events with %d of %d events succesfully added.\n", numEventsSuccessfullyAdded, numEvents);
        return PASS;
    }

fail:
    return FAIL;
}
#endif

int main(int argc, char **argv)
{
#ifdef PAPI
    int papi_errno, pass;
    int event_set;

    quiet = 0;
    char *test_quiet = getenv("PAPI_CUDA_TEST_QUIET");
    if (test_quiet)
        quiet = (int) strtol(test_quiet, (char**) NULL, 10);

    int event_count = argc - 1;

    /* if no events passed at command line, just report test skipped. */
    if (event_count == 0) {
        fprintf(stderr, "No eventnames specified at command line.\n");
        test_skip(__FILE__, __LINE__, "", 0);
    }

    papi_errno = PAPI_library_init( PAPI_VER_CURRENT );
    if (papi_errno != PAPI_VER_CURRENT) {
        test_fail(__FILE__, __LINE__, "PAPI_library_init() failed", 0);
    }

    papi_errno = PAPI_get_component_index("cuda");
    if (papi_errno < 0 ) {
        test_fail(__FILE__, __LINE__, "CUDA component not configured", 0);
    }

    event_set = PAPI_NULL;
    papi_errno = PAPI_create_eventset( &event_set );
    if (papi_errno != PAPI_OK) {
        test_fail(__FILE__, __LINE__, "PAPI_create_eventset() failed!", 0);
    }

    // Keep track of the number of events from the command line we can actually add
    // This is done to properly check the test in the function test_PAPI_add_events
    int numEventsSuccessfullyAdded = 0;
    pass = test_PAPI_add_event(&event_set, argc-1, argv+1, &numEventsSuccessfullyAdded);
    papi_errno = PAPI_cleanup_eventset(event_set);
    if (papi_errno != PAPI_OK) {
        test_fail(__FILE__, __LINE__, "PAPI_cleanup_eventset() failed!", 0);
    }

    papi_errno = PAPI_destroy_eventset(&event_set);
    if (papi_errno != PAPI_OK) {
        test_fail(__FILE__, __LINE__, "PAPI_destroy_eventset() failed!", 0);
    }

    event_set = PAPI_NULL;
    papi_errno = PAPI_create_eventset( &event_set );
    if (papi_errno != PAPI_OK) {
        test_fail(__FILE__, __LINE__, "PAPI_create_eventset() failed!", 0);
    }

    pass += test_PAPI_add_named_event(&event_set, argc-1, argv+1);
    papi_errno = PAPI_cleanup_eventset(event_set);
    if (papi_errno != PAPI_OK) {
        test_fail(__FILE__, __LINE__, "PAPI_cleanup_eventset() failed!", 0);
    }

    papi_errno = PAPI_destroy_eventset(&event_set);
    if (papi_errno != PAPI_OK) {
        test_fail(__FILE__, __LINE__, "PAPI_destroy_eventset() failed!", 0);
    }

    event_set = PAPI_NULL;
    papi_errno = PAPI_create_eventset( &event_set );
    if (papi_errno != PAPI_OK) {
        test_fail(__FILE__, __LINE__, "PAPI_create_eventset() failed!", 0);
    }

    pass += test_PAPI_add_events(&event_set, argc-1, argv+1, numEventsSuccessfullyAdded);
    papi_errno = PAPI_cleanup_eventset(event_set);
    if (papi_errno != PAPI_OK) {
        test_fail(__FILE__, __LINE__, "PAPI_cleanup_eventset() failed!", 0);
    }

    papi_errno = PAPI_destroy_eventset(&event_set);
    if (papi_errno != PAPI_OK) {
        test_fail(__FILE__, __LINE__, "PAPI_destroy_eventset() failed!", 0);
    }

    if (pass != 3)
        test_fail(__FILE__, __LINE__, "CUDA framework multipass event test failed.", 0);
    else
        test_pass(__FILE__);

    PAPI_shutdown();
#else
    fprintf(stderr, "Please compile with -DPAPI to test this feature.\n");
#endif
    return 0;
}

