/**
 * @file   hl_intercepte_single_thread_monitoring.cpp
 * @author Giuseppe Congiu
 *         gcongiu@icl.utk.edu
 *
 */
#include "common.h"
#include <pthread.h>

int quiet;

static void *run(void *thread_num_arg)
{
    int thread_num = *(int *) thread_num_arg;
    hipStream_t stream;
    hipError_t hip_errno = hipSetDevice(thread_num);
    if (hip_errno != hipSuccess) {
        hip_test_fail(__FILE__, __LINE__, "hipSetDevice", hip_errno);
    }

    hip_errno = hipStreamCreate(&stream);
    if (hip_errno != hipSuccess) {
        hip_test_fail(__FILE__, __LINE__, "hipStreamCreate", hip_errno);
    }

    void *handle;
    hip_do_matmul_init(&handle);
    hip_do_matmul_work(handle, stream);
    hip_errno = hipStreamSynchronize(stream);
    if (hip_errno != hipSuccess) {
        hip_test_fail(__FILE__, __LINE__, "hipStreamSynchronize", hip_errno);
    }
    hip_do_matmul_cleanup(&handle);

    pthread_exit(NULL);
}


int main(int argc, char *argv[])
{
    int papi_errno = PAPI_OK;
    hipError_t hip_errno = hipSuccess;
    quiet = tests_quiet(argc, argv);

    test_skip(__FILE__, __LINE__, "", papi_errno);

    setenv("HSA_TOOLS_LIB", "librocprofiler64.so", 0);
    setenv("ROCP_TOOL_LIB", "libpapi.so", 0);
    setenv("ROCP_HSA_INTERCEPT", "1", 1);

    /* NOTE: following a HIP call is made before PAPI_library_init.
     *       In such cases, ROCP_TOOL_LIB should be set to libpapi.so.
     *       This allows PAPI to set the rocprofiler environment through
     *       hsa_init() triggered by the HIP call */
    int dev_count;
    hip_errno = hipGetDeviceCount(&dev_count);
    if (hip_errno != hipSuccess) {
        test_fail(__FILE__, __LINE__, "hipGetDeviceCount", hip_errno);
    }

#define NUM_EVENTS (2)
    const char *events[NUM_EVENTS] = {
        "rocm:::SQ_INSTS_VALU",
        "rocm:::SQ_WAVES",
    };

    char event_list[512] = { 0 };
    unsigned i, off = 0;
    for (i = 0; i < dev_count; ++i) {
        unsigned j;
        for (j = 0; j < NUM_EVENTS; ++j) {
            char event[64] = { 0 };
            sprintf(event, "%s:device=%d,", events[j], i);
            strncpy(event_list + off, event, strlen(event));
            off += strlen(event);
        }
    }

    event_list[off - 1] = 0;
    setenv("PAPI_EVENTS", event_list, 1);
    setenv("PAPI_HL_THREAD_MULTIPLE", "0", 1);

    pthread_t *thread = (pthread_t *) malloc(dev_count * sizeof(*thread));
    if (NULL == thread) {
        test_fail(__FILE__, __LINE__, "malloc", PAPI_ENOMEM);
    }

    int *thread_num = (int *) malloc(dev_count * sizeof(*thread_num));
    if (NULL == thread_num) {
        test_fail(__FILE__, __LINE__, "malloc", PAPI_ENOMEM);
    }

    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);

    papi_errno = PAPI_hl_region_begin("matmul_intercept");
    if (papi_errno != PAPI_OK) {
        test_fail(__FILE__, __LINE__, "PAPI_hl_region_begin", papi_errno);
    }

    for (i = 0; i < dev_count; ++i) {
        thread_num[i] = i;
        pthread_create(&thread[i], &attr, run, &thread_num[i]);
    }

    for (i = 0; i < dev_count; ++i) {
        pthread_join(thread[i], NULL);
    }

    papi_errno = PAPI_hl_region_end("matmul_intercept");
    if (papi_errno != PAPI_OK) {
        test_fail(__FILE__, __LINE__, "PAPI_hl_region_end", papi_errno);
    }

    PAPI_hl_stop();

    free(thread);
    free(thread_num);
    test_hl_pass(__FILE__);
    return 0;
}

/**
 * @file   sample_overflow_monitoring.cpp
 * @author Giuseppe Congiu
 *         gcongiu@icl.utk.edu
 *
 * Credit to:
 *         Anthony Danalis <adanalis@icl.utk.edu>
 *         Who originally wrote the test used
 *         here as template for the SDE component.
 */
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include "common.h"

#define EV_THRESHOLD 1000

void setup_PAPI(int *event_set, int threshold);
void unset_PAPI(int event_set);

int remaining_handler_invocations = 10;
int quiet;

int main(int argc, char **argv)
{
    int papi_errno;
    hipError_t hip_errno;
    int event_set = PAPI_NULL;
    long long counter_values[1] = { 0 };
    quiet = tests_quiet(argc, argv);

    fprintf(stdout, "The rocm component does not support overflow monitoring as of now. This will be added in a future release.\n");
    test_skip(__FILE__, __LINE__,"", papi_errno);

    setenv("ROCP_HSA_INTERCEPT", "0", 1);

    setup_PAPI(&event_set, EV_THRESHOLD);

    void *handler;
    hip_do_matmul_init(&handler);

    hipStream_t stream;
    hip_errno = hipStreamCreate(&stream);
    if (hip_errno != hipSuccess) {
        hip_test_fail(__FILE__, __LINE__, "hipStreamCreate", hip_errno);
    }

    // --- Start PAPI
    papi_errno = PAPI_start(event_set);
    if (papi_errno != PAPI_OK) {
        test_fail(__FILE__, __LINE__, "PAPI_start", papi_errno);
    }

    int i;
    for (i = 0; i < 5; i++) {

        hip_do_matmul_work(handler, stream);

        // --- Read the event counters _and_ reset them
        papi_errno = PAPI_accum(event_set, counter_values);
        if (papi_errno != PAPI_OK) {
            test_fail(__FILE__, __LINE__, "PAPI_accum", papi_errno);
        }
        if (!quiet) {
            fprintf(stdout, "rocm:::SQ_WAVES:device=0 : %lld\n",
                    counter_values[0]);
            fflush(stdout);
        }

        counter_values[0] = 0;

        hip_do_matmul_work(handler, 0);

        // --- Read the event counters _and_ reset them
        papi_errno = PAPI_accum(event_set, counter_values);
        if (papi_errno != PAPI_OK) {
            test_fail(__FILE__, __LINE__, "PAPI_accum", papi_errno);
        }
        if (!quiet) {
            fprintf(stdout, "rocm:::SQ_WAVES:device=0 : %lld\n",
                    counter_values[0]);
            fflush(stdout);
        }
        counter_values[0] = 0;
    }

    // --- Stop PAPI
    papi_errno = PAPI_stop(event_set, counter_values);
    if (papi_errno != PAPI_OK) {
        test_fail(__FILE__, __LINE__, "PAPI_stop", papi_errno);
    }

    unset_PAPI(event_set);
    hip_do_matmul_cleanup(&handler);
    hip_errno = hipStreamDestroy(stream);
    if (hip_errno != hipSuccess) {
        hip_test_fail(__FILE__, __LINE__, "hipStreamDestroy", hip_errno);
    }

    if (remaining_handler_invocations <= 1) { // Let's allow for up to one missed signal, or race condition.
        test_pass(__FILE__);
    } else {
        test_fail(__FILE__, __LINE__,
                  "ROCm overflow handler was not invoked as expected!", 0);
    }

    // The following "return" is dead code, because both test_pass() and test_fail() call exit(),
    // however, we need it to prevent compiler warnings.
    return 0;
}

void overflow_handler(int event_set, void *address __attribute__((unused)),
                      long long overflow_vector,
                      void *context __attribute__((unused)))
{
    int papi_errno;
    char event_name[PAPI_MAX_STR_LEN];
    int *event_codes, event_index, number=1;

    papi_errno = PAPI_get_overflow_event_index(event_set, overflow_vector,
                                               &event_index, &number);
    if (papi_errno != PAPI_OK) {
        test_fail(__FILE__, __LINE__, "PAPI_get_overflow_event_index", papi_errno);
    }

    number = event_index + 1;
    event_codes = (int *) calloc(number, sizeof(int));

    papi_errno = PAPI_list_events(event_set, event_codes, &number);
    if (papi_errno != PAPI_OK) {
        test_fail(__FILE__, __LINE__, "PAPI_list_events", papi_errno);
    }

    papi_errno = PAPI_event_code_to_name(event_codes[event_index], event_name);
    if (papi_errno != PAPI_OK) {
        test_fail(__FILE__, __LINE__, "PAPI_event_code_to_name", papi_errno);
    }

    free(event_codes);

    if (!quiet) {
        fprintf(stdout, "Event \"%s\" at index: %d exceeded its threshold again.\n",
                event_name, event_index);
        fflush(stdout);
    }

    if (!strcmp(event_name, "rocm:::SQ_WAVES:device=0") || !event_index) {
        remaining_handler_invocations--;
    }

    return;
}

void setup_PAPI(int *event_set, int threshold)
{
    int papi_errno;
    int event_code;

    papi_errno = PAPI_library_init(PAPI_VER_CURRENT);
    if (papi_errno != PAPI_VER_CURRENT) {
        test_fail(__FILE__, __LINE__, "PAPI_library_init", papi_errno);
    }

    papi_errno = PAPI_create_eventset(event_set);
    if (papi_errno != PAPI_OK) {
        test_fail(__FILE__, __LINE__, "PAPI_create_eventset", papi_errno);
    }

    papi_errno = PAPI_event_name_to_code("rocm:::SQ_WAVES:device=0", &event_code);
    if (papi_errno != PAPI_OK) {
        test_fail(__FILE__, __LINE__, "PAPI_event_name_to_code", papi_errno);
    }

    papi_errno = PAPI_add_event(*event_set, event_code);
    if (papi_errno != PAPI_OK) {
        test_fail(__FILE__, __LINE__, "PAPI_add_event", papi_errno);
    }

    papi_errno = PAPI_overflow(*event_set, event_code, threshold,
                               PAPI_OVERFLOW_FORCE_SW, overflow_handler);
    if (papi_errno != PAPI_OK) {
        test_fail(__FILE__, __LINE__, "PAPI_overflow", papi_errno);
    }
    return;
}

void unset_PAPI(int event_set)
{
    int papi_errno;
    int event_code;

    papi_errno = PAPI_event_name_to_code("rocm:::SQ_WAVES:device=0", &event_code);
    if (papi_errno != PAPI_OK) {
        test_fail(__FILE__, __LINE__, "PAPI_event_name_to_code", papi_errno);
    }

    papi_errno = PAPI_overflow(event_set, event_code, 0, PAPI_OVERFLOW_FORCE_SW,
                               overflow_handler);
    if (papi_errno != PAPI_OK) {
        test_fail(__FILE__, __LINE__, "PAPI_overflow", papi_errno);
    }
    return;
}

/**
 * @file   matmul.cpp
 * @author Giuseppe Congiu
 *         gcongiu@icl.utk.edu
 *
 * Simple matrix to matrix multiplication kernel
 * written in hip and used by other tests in this
 * directory
 */
#include <stdio.h>
#include "common.h"

extern int quiet;
extern void hip_test_fail(const char *, int, const char *, hipError_t);

__global__ void
matmul(float *A, float *B, float *C, int N)
{
    int i = (hipBlockIdx_y * hipBlockDim_y) + hipThreadIdx_y;
    int j = (hipBlockIdx_x * hipBlockDim_x) + hipThreadIdx_x;

    if (i < N and j < N) {
        float sum = 0.0;
        for (int k = 0; k < N; ++k) {
            sum += A[(i * N) + k] * B[(k * N) + j];
        }
        C[(i * N) + j] = sum;
    }
}

struct memory {
    float *h_A;
    float *h_B;
    float *h_C;
    float *d_A;
    float *d_B;
    float *d_C;
};

void
hip_do_matmul_init(void **handle)
{
    hipError_t hip_errno;

    struct memory *handle_p = (struct memory *) malloc(sizeof(struct memory));
    if (handle_p == NULL) {
        test_fail(__FILE__, __LINE__, "malloc", PAPI_ESYS);
    }
    hip_errno = hipHostMalloc(&handle_p->h_A, sizeof(float) * ROWS * COLS);
    if (hip_errno != hipSuccess) {
        hip_test_fail(__FILE__, __LINE__, "hipHostMalloc", hip_errno);
    }
    hip_errno = hipHostMalloc(&handle_p->h_B, sizeof(float) * ROWS * COLS);
    if (hip_errno != hipSuccess) {
        hip_test_fail(__FILE__, __LINE__, "hipHostMalloc", hip_errno);
    }
    hip_errno = hipHostMalloc(&handle_p->h_C, sizeof(float) * ROWS * COLS);
    if (hip_errno != hipSuccess) {
        hip_test_fail(__FILE__, __LINE__, "hipHostMalloc", hip_errno);
    }

    hip_errno = hipMalloc(&handle_p->d_A, sizeof(float) * ROWS * COLS);
    if (hip_errno != hipSuccess) {
        hip_test_fail(__FILE__, __LINE__, "hipMalloc", hip_errno);
    }
    hip_errno = hipMalloc(&handle_p->d_B, sizeof(float) * ROWS * COLS);
    if (hip_errno != hipSuccess) {
        hip_test_fail(__FILE__, __LINE__, "hipMalloc", hip_errno);
    }
    hip_errno = hipMalloc(&handle_p->d_C, sizeof(float) * ROWS * COLS);
    if (hip_errno != hipSuccess) {
        hip_test_fail(__FILE__, __LINE__, "hipMalloc", hip_errno);
    }

    for (int i = 0; i < ROWS * COLS; ++i) {
        handle_p->h_A[i] = handle_p->h_B[i] = (float) (rand() % 1000);
        handle_p->h_C[i] = 0.0;
    }

    *handle = handle_p;
}

void
hip_do_matmul_work(void *handle, hipStream_t stream)
{
    hipError_t hip_errno;
    float *h_A, *h_B, *h_C, *d_A, *d_B, *d_C;

    struct memory *handle_p = (struct memory *) handle;
    h_A = handle_p->h_A;
    h_B = handle_p->h_B;
    h_C = handle_p->h_C;
    d_A = handle_p->d_A;
    d_B = handle_p->d_B;
    d_C = handle_p->d_C;

    hip_errno = hipMemcpyAsync(d_A, h_A, sizeof(float) * ROWS * COLS,
                               hipMemcpyHostToDevice, stream);
    if (hip_errno != hipSuccess) {
        hip_test_fail(__FILE__, __LINE__, "hipMemcpyAsync", hip_errno);
    }
    hip_errno = hipMemcpyAsync(d_B, h_B, sizeof(float) * ROWS * COLS,
                               hipMemcpyHostToDevice, stream);
    if (hip_errno != hipSuccess) {
        hip_test_fail(__FILE__, __LINE__, "hipMemcpyAsync", hip_errno);
    }

    dim3 grid_dim  = dim3(ROWS / BLOCK_DIM_X, COLS / BLOCK_DIM_Y);
    dim3 block_dim = dim3(BLOCK_DIM_X, BLOCK_DIM_Y);

    hipLaunchKernelGGL(matmul, grid_dim, block_dim, 0, stream, d_A, d_B, d_C,
                       ROWS);
    hip_errno = hipGetLastError();
    if (hip_errno != hipSuccess) {
        if (!quiet) {
            fprintf(stderr, "Error! Failed launching kernel -> '%s'\n",
                    hipGetErrorString(hip_errno));
        }
        hip_test_fail(__FILE__, __LINE__, "hipLaunchKernelGGL", hip_errno);
    }

    hip_errno = hipMemcpyAsync(h_C, d_C, sizeof(float) * ROWS * COLS,
                               hipMemcpyDeviceToHost, stream);
    if (hip_errno != hipSuccess) {
        hip_test_fail(__FILE__, __LINE__, "hipMemcpyAsync", hip_errno);
    }
}

void
hip_do_matmul_cleanup(void **handle)
{
    struct memory *handle_p = (struct memory *) (*handle);
    (void)hipFree(handle_p->h_A);
    (void)hipFree(handle_p->h_B);
    (void)hipFree(handle_p->h_C);
    (void)hipFree(handle_p->d_A);
    (void)hipFree(handle_p->d_B);
    (void)hipFree(handle_p->d_C);
    free(handle_p);
    *handle = NULL;
}

