    int thread_num = *(int *) thread_num_arg;
    char region_name[64] = { 0 };
    sprintf(region_name, "matmul_intercept-%d", thread_num);
    papi_errno = PAPI_hl_region_begin(region_name);
    if (papi_errno != PAPI_OK) {
